  gap: 8
}}>
            {chips.map(chip => <TouchableOpacity key={chip} style={[styles.chip, {
    backgroundColor: t.colors.cardDeep,
    borderRadius: t.radius.md
  }]} onPress={() => {
    touchActivity();
    setText(`${chip} `);
  }} accessibilityRole="button" accessibilityLabel={`Start with: ${chip}`}>
