      authStatus,
      unlocked,
      activeDays,
      unlockDays,
      markLoggedIn,
      setUnlockDays,
      touchActivity,
      refreshActiveDays,
      signOut,
    }),
    [authStatus, unlocked, activeDays, unlockDays, markLoggedIn, touchActivity, refreshActiveDays, signOut],
