/**
 * Mini-brain refresh: account-deletion hygiene for the daily-recompute stamp.
 *
 * The daily auto-refresh (maybeDailyRecompute) was REMOVED after the
 * red-team audit: shipping the data key to the server is only ever an
 * EXPLICIT, user-initiated act — the Question screen's button, which opens
 * the processing session itself (src/screens/QuestionScreen.tsx). No other
 * screen has a recompute affordance, so nothing may invoke a key-shipping
 * refresh automatically or on a casual gesture.
 *
 * What remains here is the stamp cleanup: installs that ran the old daily
 * job can still carry a `@mindpattern/last_recompute_<userId>` marker, and
 * the Settings screen's account-deletion flow wipes it per account.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";

/** Per-account stamp: a shared key let one account's refresh satisfy (and
 *  skip) another account's — and the upload ships the DATA KEY, so the
 *  "once per day" cap held per account. */
const stampKey = (userId: string): string => `@mindpattern/last_recompute_${userId}`;

/** Account-deletion hygiene: remove this account's recompute stamp. */
export async function clearRecomputeStamp(userId: string): Promise<void> {
  await AsyncStorage.removeItem(stampKey(userId));
}

src/components/BottomNav.tsx.source:
/**
 * The persistent bottom navigation bar (2026-09-17).
 *
 * The audit's top mobile finding: navigation lived INSIDE the Entry
 * screen's scroll content — type a 300-word entry and reaching History
 * meant scrolling past your entire text. Every main screen now renders
 * this pinned bar below its scrolling content: same five destinations
 * plus the always-present "Get help" end-cap (crisis help stays one tap
 * from every screen, matching the navigation contract in
 * src/navigation.tsx).
 *
 * With no icon library available, hierarchy stays typographic (matching
 * NavRow's approach): the active destination carries the accent color and
 * a heavier weight; "Get help" keeps its distinct help surface. Labels
 * cap their font multiplier so large text cannot break the row.
 */
import React from "react";
import { KeyboardAvoidingView, Platform, StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { useTheme } from "../theme";

export type NavDestination = "Entry" | "History" | "Insights" | "Question" | "Settings";

export interface BottomNavItem {
  key: NavDestination | "Crisis";
  label: string;
  help?: boolean;
}

export const BOTTOM_NAV_ITEMS: readonly BottomNavItem[] = [
  { key: "Entry", label: "Today" },
  { key: "History", label: "History" },
  { key: "Insights", label: "Patterns" },
  { key: "Question", label: "Question" },
  { key: "Settings", label: "Settings" },
  { key: "Crisis", label: "Get help", help: true },
] as const;

export function BottomNav({
  current,
  navigation,
}: {
  current: NavDestination | "none";
  navigation?: { navigate: (screen: string) => void };
}): React.JSX.Element {
  const t = useTheme();
  return (
    <View
      style={[styles.bar, { backgroundColor: t.colors.bg, borderTopColor: t.colors.border }]}
      accessibilityRole="tablist"
      accessibilityLabel="Main navigation"
    >
      {BOTTOM_NAV_ITEMS.map((item) => {
        const active = item.key === current;
        const help = item.help === true;
        return (
          <TouchableOpacity
            key={item.key}
            style={[
              styles.button,
              {
                backgroundColor: help ? t.colors.helpBg : active ? t.colors.card : "transparent",
                borderRadius: t.radius.md,
                minHeight: t.minTouch,
              },
            ]}
            onPress={() => navigation?.navigate(item.key)}
            accessibilityRole="tab"
            accessibilityState={active ? { selected: true } : undefined}
            accessibilityLabel={help ? "Get help — crisis resources" : item.label}
          >
            <Text
              maxFontSizeMultiplier={1.3}
              style={{
                color: help ? t.colors.text : active ? t.colors.accent : t.colors.muted,
                fontSize: 12,
                fontWeight: help ? "700" : active ? "700" : "600",
                textAlign: "center",
              }}
            >
              {item.label}
            </Text>
          </TouchableOpacity>
        );
      })}
    </View>
  );
}

/** Shared shell for the five main screens: scrolling content above, the
 *  persistent nav below. `keyboard` wraps children in the platform
 *  KeyboardAvoidingView (the Entry editor). */
export function MainShell({
  current,
  navigation,
  children,
  keyboard = false,
  keyboardBehavior,
}: {
  current: NavDestination | "none";
  navigation?: { navigate: (screen: string) => void };
  children: React.ReactNode;
  keyboard?: boolean;
  keyboardBehavior?: "padding" | undefined;
}): React.JSX.Element {
  const t = useTheme();
  const inner = <View style={styles.content}>{children}</View>;
  return (
    <View style={[styles.shell, { backgroundColor: t.colors.bg }]}>
      {keyboard ? (
        <KeyboardAvoidingView style={styles.content} behavior={keyboardBehavior}>
          {inner}
        </KeyboardAvoidingView>
      ) : (
        inner
      )}
      <BottomNav current={current} navigation={navigation} />
    </View>
  );
}

const styles = StyleSheet.create({
  shell: { flex: 1 },
  content: { flex: 1 },
  bar: {
    flexDirection: "row",
    gap: 4,
    borderTopWidth: StyleSheet.hairlineWidth,
    paddingHorizontal: 8,
    paddingTop: 6,
    paddingBottom: Platform.OS === "ios" ? 8 : 10,
  },
  button: { flex: 1, alignItems: "center", justifyContent: "center", paddingHorizontal: 2, paddingVertical: 8 },
});

src/components/InlineStatus.tsx.source:
/**
 * Transient inline confirmations — the fix for the save-feedback inversion
 * the audit found (online save = silent clear, offline save = interruptive
 * modal). Success is now a small status line that appears where the user is
 * already looking and clears itself; Alert stays reserved for failures the
 * user must act on.
 */
import React from "react";
import { StyleSheet, Text, View } from "react-native";
import { useTheme } from "../theme";

export type InlineStatusTone = "ok" | "neutral";

/** A one-line status ("Saved ✓" / "Saved — will sync when online"). The
 *  parent owns the lifetime: set the message, clear it after a moment.
 *  Announced politely to screen readers (live region). */
export function InlineStatus({ message, tone = "ok" }: { message: string | null; tone?: InlineStatusTone }) {
  const t = useTheme();
  if (!message) return null;
  return (
    <View
      style={[styles.status, { backgroundColor: t.colors.cardDeep, borderRadius: t.radius.md }]}
      accessibilityLiveRegion="polite"
      accessibilityRole="text"
      accessibilityLabel={message}
    >
      <Text style={{ color: tone === "ok" ? t.colors.success : t.colors.muted, fontSize: t.type.bodySmall.fontSize }}>
        {message}
      </Text>
    </View>
  );
}

/** A small persistent pill ("Draft restored") — calmer than a dialog, more
 *  durable than a status line. */
export function NoticeChip({ text, accessibilityLabel }: { text: string; accessibilityLabel?: string }) {
  const t = useTheme();
  return (
    <View
      style={[styles.chip, { backgroundColor: t.colors.card, borderRadius: t.radius.lg }]}
      accessibilityRole="text"
      accessibilityLabel={accessibilityLabel ?? text}
    >
      <Text style={{ color: t.colors.muted, fontSize: t.type.meta.fontSize }}>{text}</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  status: { paddingVertical: 10, paddingHorizontal: 14, alignItems: "center" },
  chip: { alignSelf: "flex-start", paddingVertical: 6, paddingHorizontal: 12 },
});

src/components/NavRow.tsx.source:
/**
 * The bottom nav row shared by the main screens. With no icon library
 * available, hierarchy comes from typography and color alone: ordinary
 * destinations sit on card surfaces, and "Get help" gets the help surface +
 * a heavier label — unmistakable without being alarming. Nav labels cap
 * their font multiplier: very large text must not break the row apart.
 */
import React from "react";
import { StyleSheet, Text, TouchableOpacity, View } from "react-native";
import { useTheme } from "../theme";

export interface NavItem {
  label: string;
  onPress: () => void;
  /** "help" marks the crisis-resources action (distinct surface + weight). */
  tone?: "default" | "help";
  accessibilityLabel?: string;
}

export function NavRow({ items }: { items: NavItem[] }): React.JSX.Element {
  const t = useTheme();
  return (
    <View style={styles.row}>
      {items.map((item) => {
        const help = item.tone === "help";
        return (
          <TouchableOpacity
            key={item.label}
            style={[
              styles.button,
              {
                backgroundColor: help ? t.colors.helpBg : t.colors.card,
                borderRadius: t.radius.md,
                minHeight: t.minTouch,
              },
            ]}
            onPress={item.onPress}
            accessibilityRole="button"
            accessibilityLabel={item.accessibilityLabel ?? item.label}
          >
            <Text
              maxFontSizeMultiplier={1.3}
              style={{
                color: help ? t.colors.text : t.colors.accent,
                fontSize: 14,
                fontWeight: help ? "700" : "600",
                textAlign: "center",
              }}
            >
              {item.label}
            </Text>
          </TouchableOpacity>
        );
      })}
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: "row", gap: 10 },
  button: { flex: 1, padding: 14, alignItems: "center", justifyContent: "center" },
});

