src/crisisDialog.ts.source:
/**
 * Crisis-dialog throttle: at most once per calendar day per account.
 *
 * The support dialog used to fire on EVERY crisis-flagged save — dialog
 * fatigue trains dismissal, and the user who needs it most stops reading
 * it. The stamp is an ISO LOCAL calendar date (the same day the entry
 * belongs to, never a UTC guess) persisted per account at
 * @mindpattern/crisis_dialog_<userId> via the encrypted secure store. Account deletion
 * must wipe it — clearCrisisDialogStamp rides the SettingsScreen deletion
 * flow, the same idiom as components/keyConsent.ts.
 *
 * The failure direction is deliberately TOWARD SHOWING: when storage is
 * unusable a process-lifetime memory mirror is the only record, so a
 * broken store can suppress a repeat dialog WITHIN one session at most —
 * a restart re-shows it. The stamp is a fatigue guard, never a gate that
 * can permanently silence support.
 */
import { secureStore } from "./secureStore";

const key = (userId: string): string => `@mindpattern/crisis_dialog_${userId}`;

/** Process-lifetime mirror, consulted ONLY when storage throws. */
const memoryStamps = new Map<string, string>();

/** True when the support dialog already ran for this account on `todayISO`. */
export async function crisisDialogShownOn(userId: string, todayISO: string): Promise<boolean> {
  try {
    return (await secureStore.getItem(key(userId))) === todayISO;
  } catch {
    // Storage unreadable: the memory mirror is the only record left.
    return memoryStamps.get(userId) === todayISO;
  }
}

/** Stamp the dialog as shown today. The mirror is always written, so a
 *  storage failure still throttles repeats within this session. */
export async function recordCrisisDialogShown(userId: string, todayISO: string): Promise<void> {
  memoryStamps.set(userId, todayISO);
  try {
    await secureStore.setItem(key(userId), todayISO);
  } catch {
    // The mirror holds it; a restart simply re-shows the dialog (fail-open).
  }
}

/** Account-deletion hygiene: the stamp must not outlive its account. */
export async function clearCrisisDialogStamp(userId: string): Promise<void> {
  memoryStamps.delete(userId);
  await secureStore.removeItem(key(userId));
}

src/crypto/envelope.ts.source:
/**
 * AES-256-GCM envelope — must match backend/app/security/crypto.py exactly.
 *
 * Wire format:  nonce(12) || ciphertext || tag(16)
 * AAD binds the blob to (context, userId, itemId) so a hostile server cannot
 * relocate blobs between entries or users undetected (see aad.ts for the
 * canonical encoding contract).
 */
import { buildAad } from "./aad";
import { engine } from "./engine";

export const NONCE_SIZE = 12;
export const KEY_SIZE = 32;
const ALGO = "aes-256-gcm";

export { buildAad };

export function generateKey(): Buffer {
  return engine.randomBytes(KEY_SIZE);
}

export function encrypt(key: Buffer, plaintext: Buffer, aad?: Buffer): Buffer {
  // The nonce is ALWAYS fresh and random — deterministic output is a
  // nonce-reuse hazard, so the fixed-nonce path is deliberately NOT
  // reachable through this signature. Test-vector generation uses
  // encryptWithFixedNonce below (unmistakably named, never called from a
  // production path).
  return encryptWithFixedNonce(key, plaintext, aad, engine.randomBytes(NONCE_SIZE));
}

/** Fixed-nonce encryption — TEST/VECTOR GENERATION ONLY (never import from
 *  a screen or store path). shared/vectors.json pins this output; mirrors
 *  the backend's crypto.encrypt_with_nonce seam removal (2026-09-16). */
export function encryptWithFixedNonce(
  key: Buffer,
  plaintext: Buffer,
  aad: Buffer | undefined,
  nonce: Buffer,
): Buffer {
  if (key.length !== KEY_SIZE) throw new Error(`key must be ${KEY_SIZE} bytes`);
  if (nonce.length !== NONCE_SIZE) throw new Error(`nonce must be ${NONCE_SIZE} bytes`);
  const cipher = engine.createCipheriv(ALGO, key, nonce);
  if (aad) cipher.setAAD(aad);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  return Buffer.concat([nonce, ciphertext, cipher.getAuthTag()]);
}

export class TamperError extends Error {
  constructor() {
    super("blob failed authentication");
    this.name = "TamperError";
  }
}

export function decrypt(key: Buffer, blob: Buffer, aad?: Buffer): Buffer {
  if (key.length !== KEY_SIZE) throw new Error(`key must be ${KEY_SIZE} bytes`);
  if (blob.length < NONCE_SIZE + 16) throw new TamperError();
  const nonce = blob.subarray(0, NONCE_SIZE);
  const tag = blob.subarray(blob.length - 16);
  const ciphertext = blob.subarray(NONCE_SIZE, blob.length - 16);
  const decipher = engine.createDecipheriv(ALGO, key, nonce);
  decipher.setAuthTag(tag);
  if (aad) decipher.setAAD(aad);
  try {
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  } catch {
    throw new TamperError();
  }
}

src/crypto/sharing.ts.source:
/**
 * Therapist sharing: the patient-side wrap of the data key — must match
 * backend/app/security/sharing.py and the web portal byte for byte.
 *
 *   shared = ECDH-P256(ephemeral_priv, therapist_pub)
 *   kek    = HKDF-SHA256(shared, salt = ephemeral_spki || therapist_spki,
 *                        info = "mindpattern/wrap/v1")
 *   wrap   = AES-256-GCM(kek, data_key,
 *                        aad = buildAad("consent-wrap", userId, therapistId))
 *
 * Public keys travel as base64 SPKI DER (91 bytes for P-256). The HKDF salt
 * pins BOTH public keys into the KEK — a wrap made for one therapist can
 * never be replayed against another — and the AAD pins the (patient,
 * therapist) pair so the server cannot relocate a wrap between consents.
 *
 * Cross-platform outputs are pinned by shared/vectors.json (wrap_vectors);
 * run `npm test` (the real modules under node:crypto) to verify.
 */
import { buildAad } from "./aad";
import { engine } from "./engine";
import { encrypt } from "./envelope";
import { zeroize } from "./kdf";

export const WRAP_CONTEXT = "consent-wrap";
const CURVE = "prime256v1";
const KEY_SIZE = 32;
const SPKI_P256_B64_LENGTH = 124; // b64(91 bytes) — exact, so a wrong key fails fast

// HKDF info rebuilt at call time (same standing as kdf.ts): every wrap
// exercises the exact label bytes.
function wrapInfo(): Buffer {
  return Buffer.from("mindpattern/wrap/v1", "utf8");
}

export interface TherapistWrap {
  /** b64 SPKI DER of the per-grant ephemeral P-256 public key. */
  ephemeralPubB64: string;
  /** b64 AES-256-GCM envelope of the data key under the derived KEK. */
  wrappedKeyB64: string;
}

/** HKDF-SHA256 over the ECDH secret with both public keys as the salt.
 * Exported for the vector test (which pins these exact bytes); production
 * callers use wrapDataKeyForTherapist. */
export function deriveWrapKek(shared: Buffer, ephemeralSpki: Buffer, therapistSpki: Buffer): Buffer {
  const derived = engine.hkdfSync(
    "sha256",
    shared,
    Buffer.concat([ephemeralSpki, therapistSpki]),
    wrapInfo(),
    KEY_SIZE,
  );
  return Buffer.from(derived as ArrayBuffer);
}

/**
 * Wrap the data key to a therapist's public wrap key. The data key LEAVES
 * the device exactly once, in this envelope — never in the clear. The
 * therapist's public key comes from the server's pairing lookup; the
 * userId/therapistId pair binds the envelope to this consent.
 */
export function wrapDataKeyForTherapist(
  dataKey: Buffer,
  therapistPubSpkiB64: string,
  userId: string,
  therapistId: string,
): TherapistWrap {
  if (dataKey.length !== KEY_SIZE) {
    throw new Error(`data key must be ${KEY_SIZE} bytes`);
  }
  // b64(91 bytes) is exactly 124 chars: a wrong-format key fails fast here,
  // and Buffer.from's lenient base64 decoding cannot mask a wrong size.
  if (therapistPubSpkiB64.length !== SPKI_P256_B64_LENGTH) {
    throw new Error("therapist public key has the wrong format");
  }
  const therapistPubDer = Buffer.from(therapistPubSpkiB64, "base64");
  if (therapistPubDer.length !== 91) {
    throw new Error("therapist public key has the wrong format");
  }

  const ephemeral = engine.generateKeyPairSync("ec", { namedCurve: CURVE });
  const ephemeralSpki = ephemeral.publicKey.export({ format: "der", type: "spki" });
  const shared = engine.diffieHellman({
    privateKey: ephemeral.privateKey,
    publicKey: engine.createPublicKey({ key: therapistPubDer, format: "der", type: "spki" }),
  });
  const kek = deriveWrapKek(shared, ephemeralSpki, therapistPubDer);
  const wrapped = encrypt(kek, dataKey, buildAad(WRAP_CONTEXT, userId, therapistId));
  zeroize(shared, kek);
  return {
    ephemeralPubB64: ephemeralSpki.toString("base64"),
    wrappedKeyB64: wrapped.toString("base64"),
  };
}

/** Human-verifiable fingerprint of a therapist's public wrap key:
 * SHA-256 over the SPKI DER, first 8 bytes as four spaced hex groups
 * ("A1B2 C3D4 E5F6 0718"). The portal shows the SAME string next to its
 * pairing code, so a patient can read it back to the therapist (or vice
 * versa) and notice a substituted key — the out-of-band check the
 * 2026-09-17 audit asked for: the server relays the key at pairing
 * lookup, and without a fingerprint nothing binds that key to the human.
 * Both platforms format identically (pinned by tests). */
export function therapistKeyFingerprint(therapistPubSpkiB64: string): string {
  const digest = engine.createHash("sha256").update(Buffer.from(therapistPubSpkiB64, "base64")).digest();
  const hex = digest.subarray(0, 8).toString("hex").toUpperCase();
  return hex.match(/.{4}/g)?.join(" ") ?? hex;
}

src/historyFind.ts.source:
/**
 * History search + calendar helpers (2026-09-17).
 *
 * Pure functions: the search box and the mood calendar filter the
 * DECRYPTED, on-device list — no query ever leaves the phone.
 */

export interface SearchableEntry {
  clientEntryId: string;
  entryDate: string;
  text: string;
}

/** Case-insensitive substring over the entry text, or an exact date match
 *  (so "2026-07" filters to July, "2026-07-14" to the day). */
export function filterEntries<T extends SearchableEntry>(entries: T[], query: string): T[] {
  const q = query.trim().toLowerCase();
  if (!q) return entries;
  return entries.filter((e) => e.text.toLowerCase().includes(q) || e.entryDate.toLowerCase().includes(q));
}

export interface CalendarDay {
  /** ISO date (YYYY-MM-DD) or null for the leading blanks. */
  iso: string | null;
  /** Day-of-month number to render. */
  day: number;
}

/** One month grid: leading blanks for the weekday offset, then every day.
 *  Weeks start Monday (matches the engine's weekday semantics). */
export function monthGrid(year: number, month1to12: number): CalendarDay[] {
  const first = new Date(Date.UTC(year, month1to12 - 1, 1));
  const daysInMonth = new Date(Date.UTC(year, month1to12, 0)).getUTCDate();
  // JS getUTCDay: Sunday=0 … Saturday=6; Monday-first offset:
  const lead = (first.getUTCDay() + 6) % 7;
  const cells: CalendarDay[] = [];
  for (let i = 0; i < lead; i++) cells.push({ iso: null, day: 0 });
  for (let d = 1; d <= daysInMonth; d++) {
    cells.push({
      iso: `${year}-${String(month1to12).padStart(2, "0")}-${String(d).padStart(2, "0")}`,
      day: d,
    });
  }
  return cells;
}

export const MONTH_NAMES = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
] as const;

export function monthLabel(year: number, month1to12: number): string {
  return `${MONTH_NAMES[month1to12 - 1]} ${year}`;
}

/** Previous/next month stepping (wraps the year). */
export function stepMonth(year: number, month1to12: number, delta: -1 | 1): { year: number; month: number } {
  const zero = month1to12 - 1 + delta;
  return { year: year + Math.floor(zero / 12), month: ((zero % 12) + 12) % 12 + 1 };
}

src/onboarding.ts.source:
/**
 * First-run onboarding state: shown ONCE after a registration, never after
 * a plain login or an unlock.
 *
 * Two pieces of state:
 *  - a MEMORY-ONLY "pending" flag: LoginScreen sets it the moment a
 *    registration succeeds; the navigator consumes it (exactly once) when
 *    the main flow first renders. Login and unlock never set it, so those
 *    paths never see onboarding. Memory-only also means it cannot outlive
 *    the session it was registered in — a restart before onboarding simply
 *    lands on the journal.
 *  - a PERSISTED per-account "seen" flag (the components/keyConsent.ts
 *    idiom): written when onboarding completes, wiped on account deletion.
 *    It is the belt-and-braces guard — landing on the onboarding screen
 *    with the flag already set routes straight to the journal instead of
 *    lecturing twice.
 *
 * Losing the flag to a storage error is fail-safe in the honest direction:
 * worst case, three short calm panels show once more.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";

const key = (userId: string): string => `@mindpattern/onboarding_seen_${userId}`;

let pending = false;

/** Mark that THIS session just created its account — the navigator routes
 *  the first render of the main flow through onboarding. */
export function queueOnboarding(): void {
  pending = true;
}

/** One-shot read: true exactly once per queueOnboarding() call, so a later
 *  login inside the same session can never trigger onboarding. */
export function takePendingOnboarding(): boolean {
  const wasPending = pending;
  pending = false;
  return wasPending;
}

export async function hasSeenOnboarding(userId: string): Promise<boolean> {
  return (await AsyncStorage.getItem(key(userId))) !== null;
}

export async function recordOnboardingSeen(userId: string): Promise<void> {
  await AsyncStorage.setItem(key(userId), "1");
}

/** Account-deletion hygiene: the flag must not outlive its account. */
export async function clearOnboardingSeen(userId: string): Promise<void> {
  await AsyncStorage.removeItem(key(userId));
}

src/promptChips.ts.source:
/**
 * Gentle writing starters for blank-page days (2026-09-17).
 *
 * Depression's blank-page paralysis is a documented journaling barrier;
 * three rotating starters above an empty editor give the first words
 * without steering content. The pool is deliberately non-clinical — no
 * CBT scaffolding, no "should" — matching the app's observation-only
 * voice. Selection is DETERMINISTIC per day (a seeded shuffle over the
 * date ordinal): no RNG, testable, and the same chips stay put within a
 * day so they don't visually flicker on re-renders.
 */

export const PROMPT_CHIPS: readonly string[] = [
  "Today I noticed…",
  "One small thing that happened…",
  "On my mind right now…",
  "Something I want to remember…",
  "Today felt…",
  "A moment worth keeping…",
  "I didn't expect…",
  "Someone I thought of today…",
  "The best part of today…",
  "The hardest part of today…",
  "Something I'm looking forward to…",
  "If today had a title…",
  "My body feels…",
  "The weather matched my mood when…",
  "One thing I did for myself…",
  "Something I keep putting off…",
  "A sound I heard today…",
  "Somewhere I went today…",
  "I felt most like myself when…",
  "Something that surprised me…",
] as const;

/** Deterministic per-day selection: a multiplicative hash of the date
 *  ordinal picks the rotation offset, then the first `count` pool entries
 *  (wrapping) come out in pool order. Same day → same chips, forever. */
export function promptChipsFor(day: Date, count = 3): string[] {
  const ordinal = Math.floor(day.getTime() / 86_400_000);
  // A small odd multiplier spreads consecutive days across the pool.
  const offset = ((ordinal * 7) % PROMPT_CHIPS.length + PROMPT_CHIPS.length) % PROMPT_CHIPS.length;
  const chips: string[] = [];
  const total = Math.min(count, PROMPT_CHIPS.length);
  for (let i = 0; i < total; i++) {
    const chip = PROMPT_CHIPS[(offset + i) % PROMPT_CHIPS.length];
    if (chip !== undefined) chips.push(chip);
  }
  return chips;
}

src/screens/PrivacyScreen.tsx.source:
/**
 * The privacy policy, in plain language, offline. Static content — like the
 * crisis screen it needs no network, no vault, and no account. Every
 * sentence mirrors the security model in the repository README; when the
 * model changes, both change together.
 */
import React from "react";
import { ScrollView, StyleSheet, Text, View } from "react-native";
import { useTheme } from "../theme";
import { CrisisHelpButton } from "../components/buttons";

const SECTIONS: readonly { title: string; body: string }[] = [
  {
    title: "What is encrypted",
    body: "Everything you write. Your password derives the encryption keys on this device, and entries are encrypted before they leave it. The server stores only ciphertext. There is no password reset. If you forget your password, no one — including us — can recover your journal.",
  },
  {
    title: "What the server sees",
    body: "Your username, the calendar dates you wrote on, when each entry arrived, and how large each encrypted entry is. A leak of the server's database reveals when and how much you wrote — never what.",
  },
  {
    title: "The one exception: pattern analysis",
    body: "Patterns are computed by the server, which needs your entries decrypted once to do it. When you start an analysis yourself, your key is sent once over an encrypted connection, held in memory for up to 5 minutes, used, and destroyed. It is never stored, and it is never sent for any other reason.",
  },
  {
    title: "Optional AI analysis",
    body: "Off by default for every account. If you turn it on, your decrypted entries are sent to a third-party AI provider chosen by the server operator, and that provider's data-retention policy applies. Turning it on asks for your password, so a borrowed phone cannot change it.",
  },
  {
    title: "Deleting your data",
    body: "Deleting your account removes your entries, patterns, and account from the live database. Database backups and server logs expire on the operator's own schedule — deletion cannot reach back into them. An exported bundle includes everything and stays yours to keep or delete.",
  },
];

export function PrivacyScreen({ navigation }: { navigation: any }): React.JSX.Element {
  const t = useTheme();
  return (
    <ScrollView
      style={[styles.container, { backgroundColor: t.colors.bg }]}
      contentContainerStyle={{ padding: t.spacing.xl, gap: 14 }}
    >
      <Text style={[styles.headline, { color: t.colors.text }]}>Privacy, in plain language</Text>
      {SECTIONS.map((section) => (
        <View key={section.title} style={{ gap: 6 }}>
          <Text style={[styles.sectionTitle, { color: t.colors.accent }]}>{section.title}</Text>
          <Text style={[styles.body, { color: t.colors.body }]}>{section.body}</Text>
        </View>
      ))}
      <Text style={{ color: t.colors.muted, fontSize: t.type.meta.fontSize, lineHeight: 17 }}>
        This policy lives inside the app — reading it needs no connection and leaves no trace anywhere.
      </Text>
      <CrisisHelpButton onPress={() => navigation.navigate("Crisis")} />
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  headline: { fontSize: 22, fontWeight: "700", lineHeight: 29 },
  sectionTitle: { fontSize: 12, fontWeight: "700", letterSpacing: 1.5, textTransform: "uppercase" },
  body: { fontSize: 15, lineHeight: 22 },
});

src/unlockProof.ts.source:
/**
 * Offline unlock proof (C1 fix).
 *
 * The old offline-unlock path derived keys from the password and a cached
 * salt and unlocked the vault with NO verification — any string "unlocked"
 * the app offline, and a mistyped password then encrypted new entries
 * under a wrong data key (permanently undecryptable).
 *
 * At every ONLINE login we seal a fixed marker under the data key. Offline
 * unlock now proves the password: derive, try to open the seal, and only
 * unlock on success. A wrong password fails the AEAD authentication.
 *
 * Threat-model note: this makes the device itself an offline oracle for
 * password GUESSES — that trade-off is inherent to any local unlock and
 * is bounded by PBKDF2(600k) per guess plus a deliberate delay on
 * failure. The seal reveals nothing about the key beyond guess correctness.
 */
import AsyncStorage from "@react-native-async-storage/async-storage";
import { buildAad, decrypt, encrypt } from "./crypto/envelope";

const proofKey = (userId: string): string => `@mindpattern/unlockproof_${userId}`;
const PROOF_PLAINTEXT = Buffer.from("mindpattern-unlock-proof/v1", "utf8");

/** Call exactly once after a VERIFIED online login (or registration):
 *  seals the marker under the account's data key. */
export async function storeUnlockProof(dataKey: Buffer, userId: string): Promise<void> {
  const blob = encrypt(dataKey, PROOF_PLAINTEXT, buildAad("unlockproof", userId));
  await AsyncStorage.setItem(proofKey(userId), blob.toString("base64"));
}

export type ProofResult = "ok" | "wrong" | "absent";

/** Prove a derived data key offline. */
export async function verifyUnlockProof(dataKey: Buffer, userId: string): Promise<ProofResult> {
  const raw = await AsyncStorage.getItem(proofKey(userId));
  if (!raw) return "absent";
  try {
    const plain = decrypt(dataKey, Buffer.from(raw, "base64"), buildAad("unlockproof", userId));
    return plain.equals(PROOF_PLAINTEXT) ? "ok" : "wrong";
  } catch {
    return "wrong";
  }
}

export async function clearUnlockProof(userId: string): Promise<void> {
  await AsyncStorage.removeItem(proofKey(userId));
}

export async function unlockProofExists(userId: string): Promise<boolean> {
  return (await AsyncStorage.getItem(proofKey(userId))) !== null;
}

src/vault.ts.source:
/**
 * Session-scoped key vault. Holds the unlocked keys in memory only —
 * never AsyncStorage, never disk. Zeroized on sign-out / account deletion.
 *
 * The vault is observable: the bearer token survives an app restart on
 * disk, but these keys do not, so navigation subscribes and shows the
 * unlock screen until the user re-derives them from their password.
 *
 * The vault also records WHICH account the keys belong to (ownerUserId).
 * Every operation that ships a key to the server (processing sessions)
 * must check that binding: without it, a session/vault desync would
 * deliver one account's data key into another account's session.
 */
import type { Keys } from "./crypto/MindPatternCrypto";
import { zeroize } from "./crypto/kdf";

type Listener = () => void;
const listeners = new Set<Listener>();

function notify(): void {
  for (const listener of listeners) listener();
}

/** What an unlocked session actually holds. The master key is NOT retained:
 *  unlock() zeroizes it immediately, and keeping the (zeroed) field on the
 *  stored state only invited a future caller to read dead bytes silently. */
export type SessionKeys = Pick<Keys, "authKey" | "dataKey">;

let current: SessionKeys | null = null;
let ownerUserId: string | null = null;

export const vault = {
  /** Unlock with the account these keys were derived for. The id is what
   *  lets key-shipping operations prove the keys match the session. */
  unlock(keys: Keys, userId?: string): void {
    if (current) zeroize(current.authKey, current.dataKey);
    zeroize(keys.masterKey); // only auth/data keys are useful from here on
    current = { authKey: keys.authKey, dataKey: keys.dataKey };
    ownerUserId = userId ?? null;
    notify();
  },
  get(): SessionKeys {
    if (!current) throw new Error("vault is locked");
    // A fresh object per call: callers cannot mutate the vault's own
    // reference or swap its keys. The buffers are shared on purpose —
    // zeroize-on-lock must still reach every copy.
    return { authKey: current.authKey, dataKey: current.dataKey };
  },
  isUnlocked(): boolean {
    return current !== null;
  },
  /** The account id the unlocked keys belong to, or null if unknown
   *  (legacy callers) — key-shipping code must treat null as unverified. */
  ownerUserId(): string | null {
    return ownerUserId;
  },
  lock(): void {
    if (current) zeroize(current.authKey, current.dataKey);
    current = null;
    ownerUserId = null;
    notify();
  },
  subscribe(listener: Listener): () => void {
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  },
};

