/**
 * CrisisScreen: the most safety-critical screen in the app. Pins the
 * hotline resources, the honest disclaimer, the per-platform sms: URL
 * (iOS drops Android's "?body=" silently), and that a failed
 * Linking.openURL NEVER becomes a dead tap.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";
import React from "react";
import { Alert } from "react-native";

// rnMock has no Linking and pins Platform.OS to "ios"; this screen needs
// both controllable, so this file layers its own react-native mock (the
// alias still resolves the base primitives from rnMock).
const mocks = vi.hoisted(() => ({
  openURL: vi.fn(async (_url: string) => true),
  platform: { os: "ios" as "ios" | "android" },
}));
vi.mock("react-native", async (importOriginal) => {
  const actual = await importOriginal<typeof import("react-native")>();
  return {
    ...actual,
    Platform: {
      OS: mocks.platform.os,
      select: <T,>(opts: { ios?: T; android?: T; native?: T; default?: T }): T => {
        const perPlatform = mocks.platform.os === "ios" ? opts.ios : opts.android;
        return perPlatform ?? opts.native ?? (opts.default as T);
      },
    },
    Linking: { openURL: mocks.openURL },
  };
});

const { CrisisScreen } = await import("../../src/screens/CrisisScreen");
const { render, flush, textOf, pressLabel } = await import("../helpers/rtr");

beforeEach(() => {
  mocks.openURL.mockReset();
  mocks.openURL.mockImplementation(async () => true);
  Alert.alert.mockClear();
  mocks.platform.os = "ios";
});

describe("CrisisScreen content", () => {
  it("pins the hotline resources: 988, Crisis Text Line 741741, 911, findahelpline.com", async () => {
    const root = await render(<CrisisScreen />);
    const text = textOf(root);
    expect(text).toContain("Call or text 988");
    expect(text).toContain("988 Suicide & Crisis Lifeline");
    expect(text).toContain("Text HOME to 741741");
    expect(text).toContain("Crisis Text Line");
    expect(text).toContain("Call 911");
    expect(text).toContain("findahelpline.com");
  });

  it("pins the honest disclaimer (not therapy, not a medical device, not an emergency service)", async () => {
    const root = await render(<CrisisScreen />);
    expect(textOf(root)).toContain(
      "It is not therapy, not a medical device, and not an emergency service.",
    );
  });
});

describe("CrisisScreen actions", () => {
  it("opens tel:988 for the lifeline and tel:911 for emergencies", async () => {
    const root = await render(<CrisisScreen />);
    await pressLabel(root, "Call or text 988");
    await pressLabel(root, "Call 911");
    expect(mocks.openURL.mock.calls).toEqual([["tel:988"], ["tel:911"]]);
  });

  it("pre-fills HOME with '&body=' on iOS (regression: '?body=' is silently dropped)", async () => {
    mocks.platform.os = "ios";
    const root = await render(<CrisisScreen />);
    await pressLabel(root, "Text HOME to 741741");
    expect(mocks.openURL).toHaveBeenCalledWith("sms:741741&body=HOME");
  });

  it("pre-fills HOME with '?body=' on Android", async () => {
    mocks.platform.os = "android";
    const root = await render(<CrisisScreen />);
    await pressLabel(root, "Text HOME to 741741");
    expect(mocks.openURL).toHaveBeenCalledWith("sms:741741?body=HOME");
  });

  it("opens findahelpline.com for non-US users", async () => {
    const root = await render(<CrisisScreen />);
    await pressLabel(root, "Open findahelpline.com");
    expect(mocks.openURL).toHaveBeenCalledWith("https://findahelpline.com");
  });
});

describe("CrisisScreen failure handling", () => {
  it.each([
    ["Call or text 988", "988"],
    ["Text HOME to 741741", "741741"],
    ["Call 911", "911"],
    ["Open findahelpline.com", "findahelpline.com"],
  ])("a rejected openURL on %j surfaces the number/address instead of a dead tap", async (label, fallback) => {
    mocks.openURL.mockRejectedValueOnce(new Error("no application registered"));
    const root = await render(<CrisisScreen />);
    await pressLabel(root, label);
    await flush();
    // Handled: the rejection became a dialog carrying the manual fallback,
    // not an unhandled promise rejection.
    expect(Alert.alert).toHaveBeenCalledWith(
      "Couldn't open it from here",
      expect.stringContaining(fallback),
    );
  });
});

describe("CrisisScreen upgrades (call anxiety + chat + locale)", () => {
  it("says what calling is like — the #1 barrier to hotline use", async () => {
    const root = await render(<CrisisScreen />);
    const text = textOf(root);
    expect(text).toContain("What to expect when you call or text");
    expect(text).toContain("as much or as little as you want");
    expect(text).toContain("no script and no wrong way to start");
  });

  it("offers the 988 chat alongside call and text", async () => {
    const root = await render(<CrisisScreen />);
    expect(textOf(root)).toContain("Chat online at 988lifeline.org");
    await pressLabel(root, "Chat online at 988lifeline.org");
    expect(mocks.openURL).toHaveBeenCalledWith("https://988lifeline.org/chat");
  });

  it("a rejected chat open speaks the address (no dead taps)", async () => {
    mocks.openURL.mockRejectedValueOnce(new Error("no browser"));
    const root = await render(<CrisisScreen />);
    await pressLabel(root, "Chat online at 988lifeline.org");
    await flush();
    expect(Alert.alert).toHaveBeenCalledWith("Couldn't open it from here", expect.stringContaining("988lifeline.org/chat"));
  });

  it("US layout (default): hotlines first, findahelpline as the outside-US note", async () => {
    const root = await render(<CrisisScreen />);
    const texts = (await import("../helpers/rtr")).allText(root);
    const i988 = texts.findIndex((t) => t.includes("Call or text 988"));
    const iFah = texts.findIndex((t) => t.includes("Open findahelpline.com"));
    expect(i988).toBeGreaterThanOrEqual(0);
    expect(iFah).toBeGreaterThan(i988);
    expect(textOf(root)).toContain("These are US services");
  });

  it("non-US region: findahelpline leads, US services labeled US-only", async () => {
    const root = await render(<CrisisScreen region="DE" />);
    const texts = (await import("../helpers/rtr")).allText(root);
    const iFah = texts.findIndex((t) => t.includes("Open findahelpline.com"));
    const i988 = texts.findIndex((t) => t.includes("Call or text 988"));
    expect(iFah).toBeGreaterThanOrEqual(0);
    expect(i988).toBeGreaterThan(iFah);
    expect(textOf(root)).toContain("988 and 741741 are US-only");
  });

  it("non-US region: the 911 action carries the US-only label too (and still dials)", async () => {
    const root = await render(<CrisisScreen region="DE" />);
    expect(textOf(root)).toContain("Call 911 (US)");
    await pressLabel(root, "Call 911 (US)");
    expect(mocks.openURL).toHaveBeenCalledWith("tel:911");
  });

  it("an explicit US region keeps the US-first layout", async () => {
    const root = await render(<CrisisScreen region="US" />);
    const texts = (await import("../helpers/rtr")).allText(root);
    expect(texts.findIndex((t) => t.includes("Call or text 988"))).toBeLessThan(
      texts.findIndex((t) => t.includes("Open findahelpline.com")),
    );
  });

  it("every action has a 44pt target and a screen-reader label", async () => {
    const root = await render(<CrisisScreen />);
    const { allStyles, touchableByLabel } = await import("../helpers/rtr");
    expect(allStyles(root).some((s) => s.minHeight === 44)).toBe(true);
    expect(touchableByLabel(root, "Call or text 988").props.accessibilityLabel).toContain("988 Suicide & Crisis Lifeline");
    expect(touchableByLabel(root, "Open findahelpline.com").props.accessibilityRole).toBe("link");
    expect(touchableByLabel(root, "Open findahelpline.com").props.hitSlop).toEqual({ top: 12, bottom: 12, left: 12, right: 12 });
  });
});

describe("deviceRegion", () => {
  it("parses the locale region and survives hostile Intl implementations", async () => {
    const { deviceRegion } = await import("../../src/screens/CrisisScreen");
    // Default node locale parses or returns null — both are valid shapes.
    const detected = deviceRegion();
    expect(detected === null || /^[A-Z]{2}$/.test(detected)).toBe(true);

    const original = Intl.DateTimeFormat;
    try {
      // A locale with no region subtag.
      vi.stubGlobal("Intl", {
        ...Intl,
        DateTimeFormat: () => ({ resolvedOptions: () => ({ locale: "en" }) }),
      });
      expect(deviceRegion()).toBeNull();
      // Intl throws entirely (ancient Hermes): US-first, no crash.
      vi.stubGlobal("Intl", {
        DateTimeFormat: () => {
          throw new Error("no intl");
        },
      });
      expect(deviceRegion()).toBeNull();
    } finally {
      vi.stubGlobal("Intl", original);
    }
  });
});

tests/historyFind.test.tsx.source:
/**
 * History search + mood calendar (2026-09-17): pure-function pins for the
 * filter and the month grid, plus component behavior for the calendar.
 */
import { describe, expect, it, vi } from "vitest";

const { filterEntries, monthGrid, monthLabel, stepMonth } = await import("../src/historyFind");
const { MoodCalendar } = await import("../src/components/MoodCalendar");
const { render, textOf } = await import("./helpers/rtr");

describe("filterEntries", () => {
  const entries = [
    { clientEntryId: "a", entryDate: "2026-09-01", text: "walked by the river" },
    { clientEntryId: "b", entryDate: "2026-09-02", text: "Busy work day at the office" },
    { clientEntryId: "c", entryDate: "2026-08-15", text: "quiet evening" },
  ];

  it("empty query returns everything unchanged", () => {
    expect(filterEntries(entries, "")).toEqual(entries);
    expect(filterEntries(entries, "   ")).toEqual(entries);
  });

  it("matches case-insensitively over the text", () => {
    expect(filterEntries(entries, "RIVER").map((e) => e.clientEntryId)).toContain("a");
    expect(filterEntries(entries, "office")).toHaveLength(1);
  });

  it("matches dates: full day and month prefix", () => {
    expect(filterEntries(entries, "2026-09-02")).toHaveLength(1);
    expect(filterEntries(entries, "2026-09")).toHaveLength(2);
    expect(filterEntries(entries, "2026")).toHaveLength(3);
  });

  it("no match yields an empty list, never an error", () => {
    expect(filterEntries(entries, "zzzz-not-there")).toEqual([]);
  });
});

describe("monthGrid", () => {
  it("September 2026 starts on a Tuesday (Monday-first: one leading blank)", () => {
    const cells = monthGrid(2026, 9);
    expect(cells[0]).toEqual({ iso: null, day: 0 });
    expect(cells[1]).toEqual({ iso: "2026-09-01", day: 1 });
    expect(cells).toHaveLength(30 + 1);
  });

  it("February 2028 (leap) has 29 days plus one leading blank (starts Tuesday)", () => {
    const cells = monthGrid(2028, 2);
    expect(cells[0]).toEqual({ iso: null, day: 0 });
    expect(cells[1]).toEqual({ iso: "2028-02-01", day: 1 });
    expect(cells).toHaveLength(30);
  });

  it("labels and stepping wrap the year", () => {
    expect(monthLabel(2026, 9)).toBe("September 2026");
    expect(stepMonth(2026, 1, -1)).toEqual({ year: 2025, month: 12 });
    expect(stepMonth(2026, 12, 1)).toEqual({ year: 2027, month: 1 });
    expect(stepMonth(2026, 9, -1)).toEqual({ year: 2026, month: 8 });
  });
});

describe("MoodCalendar", () => {
  const dayMoods = { "2026-09-01": 0.5, "2026-09-02": -0.8 };

  async function calendar(overrides?: Partial<Parameters<typeof MoodCalendar>[0]>) {
    return render(
      <MoodCalendar
        dayMoods={dayMoods}
        journaledDays={new Set(["2026-09-01", "2026-09-02"])}
        selectedDay={null}
        onSelectDay={() => {}}
        {...overrides}
      />,
    );
  }

  it("renders the weekday header and the month label", async () => {
    const root = await calendar();
    const now = new Date();
    const label = `${now.toLocaleString("en-US", { month: "long" })} ${now.getFullYear()}`;
    expect(textOf(root)).toContain(label);
    expect(textOf(root)).toContain("M"); // Monday-first header marker
  });

  it("tapping a journaled day selects it; tapping the selection again deselects", async () => {
    const onSelectDay = vi.fn();
    const root = await calendar({ onSelectDay });
    const journaled = root.root
      .findAll((n) => typeof n.props?.accessibilityLabel === "string")
      .map((n) => n.props.accessibilityLabel as string)
      .find((label: string) => /^\d{4}-\d{2}-\d{2}, journaled/.test(label));
    expect(journaled).toBeTruthy();
    const day = journaled!.split(",")[0]!;
    // First tap selects the day's ISO date; the selection state re-renders
    // with "selected" and a second tap would pass null.
    const button = root.root
      .findAll((n) => n.props?.accessibilityLabel === journaled && typeof n.props?.onPress === "function")[0];
    expect(button).toBeDefined();
    button!.props.onPress();
    expect(onSelectDay).toHaveBeenCalledWith(day);
  });

  it("a blank day clears a selected filter instead of trapping the person in it", async () => {
    const onSelectDay = vi.fn();
    const root = await calendar({ onSelectDay, selectedDay: "2026-09-01" });
    const blank = root.root.findAll((n) => n.props?.accessibilityLabel === "not-a-real-label");
    expect(blank).toHaveLength(0);
    // Every enabled day button carries an ISO accessibility label.
    const labels = root.root
      .findAll((n) => typeof n.props?.accessibilityLabel === "string")
      .map((n) => n.props.accessibilityLabel as string)
      .filter((l) => /\d{4}-\d{2}-\d{2}/.test(l));
    expect(labels.length).toBeGreaterThan(20);
    const blankDay = root.root.findAll(
      (n) => typeof n.props?.accessibilityLabel === "string" && n.props.accessibilityLabel.endsWith(", no entry") && typeof n.props?.onPress === "function",
    )[0];
    expect(blankDay).toBeDefined();
    blankDay!.props.onPress();
    expect(onSelectDay).toHaveBeenCalledWith(null);
  });
});

tests/smallModules.pins.test.ts.source:
/**
 * Deep-mutation pins for the small modules (2026-09-15 Stryker campaign):
 *  - secureStore: an envelope whose `c` is a byte ARRAY reads as absent (the
 *    typeof-string guard is real), and a v1-path failure falls into the
 *    legacy path — pinned by an envelope whose JSON text itself base64-
 *    decodes to a valid forgery-free blob (only the emptied catch would
 *    return it),
 *  - unlockProof: the sealed marker plaintext is exactly
 *    "mindpattern-unlock-proof/v1", and unlockProofExists is really false
 *    when nothing is stored,
 *  - entryId: the + and / base64url mappings with stubbed engine bytes,
 *  - onboarding: a fresh module starts with NO pending onboarding, and the
 *    persisted seen sentinel is exactly "1",
 *  - genericQuestions: the exact per-date pick (djb2 ×33),
 *  - kdf: the async derivation accepts an exactly-8-byte salt,
 *  - envelope: a supplied nonce of the wrong length fails loudly.
 *
 * Equivalents are suppressed at the source (secureStore's deviceKey cache
 * fast path, the utf8 encoding literal; entryId's unreachable padding
 * strip; genericQuestions' loop bound — see those files).
 */
// @ts-nocheck

import { beforeEach, describe, expect, it, vi } from "vitest";
import storage from "./helpers/storageMock";

const { encrypt, encryptWithFixedNonce, decrypt, buildAad } = await import("../src/crypto/envelope");
const { deriveMasterKeyAsync, MIN_ITERATIONS } = await import("../src/crypto/kdf");

beforeEach(() => {
  storage.__reset();
});

/** A fresh secureStore module graph backed by a KNOWN device key. */
async function freshSecureStore(key: Buffer) {
  vi.resetModules();
  const freshStorage = (await import("@react-native-async-storage/async-storage")).default as typeof storage;
  await freshStorage.setItem("@mindpattern/device_k", key.toString("base64"));
  const mod = await import("../src/secureStore");
  return { freshStorage, secureStore: mod.secureStore };
}

describe("secureStore pins", () => {
  it("an envelope whose c is a byte ARRAY reads as absent, not as decryptable", async () => {
    const key = Buffer.alloc(32, 9);
    const { freshStorage, secureStore } = await freshSecureStore(key);
    // A perfectly valid ciphertext — planted under c as JSON numbers.
    const blob = encrypt(key, Buffer.from("array-envelope-secret"));
    await freshStorage.setItem("k", JSON.stringify({ v: 1, c: Array.from(blob) }));
    // typeof c !== "string" must hold the line: the mutant would feed the
    // array through Buffer.from(numbers) and return the plaintext.
    expect(await secureStore.getItem("k")).toBeNull();
  });

  it("an emptied v1 catch falls through to the legacy path — pinned with a self-decoding envelope", async () => {
    // Construct an envelope string whose base64-valid characters ("v1c" +
    // c) decode to a REAL ciphertext: nonce chosen so the first three
    // base64 chars of the blob are exactly "v1c".
    const key = Buffer.alloc(32, 9);
    const { freshStorage, secureStore } = await freshSecureStore(key);
    const nonce = Buffer.from([0xbf, 0x57, 0x3f, 0, 0, 0, 0, 0, 0, 0, 0, 0]);
    const blob = encryptWithFixedNonce(key, Buffer.from("forged-legacy-secret"), undefined, nonce);
    const s = blob.toString("base64");
    expect(s.startsWith("v1c")).toBe(true); // the construction holds
    const c = s.slice(3);
    const raw = `{"v":1,"c":"${c}"}`;
    // Precondition 1: c on its own must fail decryption (so the v1 path
    // throws and the catch decides the outcome).
    expect(() => decrypt(key, Buffer.from(c, "base64"))).toThrow();
    // Precondition 2: the envelope's own filtered characters decode to the
    // valid blob — exactly what the legacy path would feed to decrypt if
    // the catch were emptied.
    expect(decrypt(key, Buffer.from(raw.replace(/[^A-Za-z0-9+/=]/g, ""), "base64")).toString("utf8")).toBe(
      "forged-legacy-secret",
    );
    await freshStorage.setItem("k", raw);
    // The intact catch returns null; the emptied-catch mutant falls through
    // to the legacy path and returns the forged-looking plaintext.
    expect(await secureStore.getItem("k")).toBeNull();
  });
});

describe("unlockProof pins", () => {
  // The secureStore tests above call vi.resetModules(), so every later test
  // must import the storage helper and the module under test from the SAME
  // fresh module graph (the top-level `storage` binding points at the old,
  // orphaned instance).
  it("the sealed marker is exactly 'mindpattern-unlock-proof/v1'", async () => {
    const s = (await import("./helpers/storageMock")).default;
    const { storeUnlockProof } = await import("../src/unlockProof");
    const dataKey = Buffer.alloc(32, 7);
    await storeUnlockProof(dataKey, "u9");
    const raw = await s.getItem("@mindpattern/unlockproof_u9");
    expect(raw).not.toBeNull();
    const plain = decrypt(dataKey, Buffer.from(raw, "base64"), buildAad("unlockproof", "u9"));
    expect(plain.toString("utf8")).toBe("mindpattern-unlock-proof/v1");
  });

  it("unlockProofExists is genuinely false when nothing is stored (and after clear)", async () => {
    const s = (await import("./helpers/storageMock")).default;
    await s.__reset();
    const { storeUnlockProof, clearUnlockProof, unlockProofExists } = await import("../src/unlockProof");
    expect(await unlockProofExists("u-none")).toBe(false);
    const dataKey = Buffer.alloc(32, 7);
    await storeUnlockProof(dataKey, "u1");
    expect(await unlockProofExists("u1")).toBe(true);
    await clearUnlockProof("u1");
    expect(await unlockProofExists("u1")).toBe(false);
  });
});

describe("entryId pins", () => {
  it("maps + and / to - and _ exactly (stubbed engine bytes)", async () => {
    const { engine } = await import("../src/crypto/engine");
    const { newClientEntryId } = await import("../src/entryId");
    // base64 of [0xfb,0,0, 0xff,0,0, 0,0,0] is "+wAA/wAAAAAA" — one of each
    // special character, and no padding (9 bytes is a multiple of 3).
    const original = engine.randomBytes;
    try {
      engine.randomBytes = (() => Buffer.from([0xfb, 0, 0, 0xff, 0, 0, 0, 0, 0])) as typeof engine.randomBytes;
      expect(newClientEntryId("2026-01-31")).toBe("e-2026-01-31--wAA_wAAAAAA");
    } finally {
      engine.randomBytes = original;
    }
  });
});

describe("onboarding pins", () => {
  it("a fresh module starts with NO pending onboarding", async () => {
    vi.resetModules();
    const fresh = await import("../src/onboarding");
    expect(fresh.takePendingOnboarding()).toBe(false);
    fresh.queueOnboarding();
    expect(fresh.takePendingOnboarding()).toBe(true);
    expect(fresh.takePendingOnboarding()).toBe(false);
  });

  it("recordOnboardingSeen persists exactly the '1' sentinel", async () => {
    const s = (await import("./helpers/storageMock")).default;
    const { recordOnboardingSeen } = await import("../src/onboarding");
    await recordOnboardingSeen("user-1");
    expect(await s.getItem("@mindpattern/onboarding_seen_user-1")).toBe("1");
  });
});

describe("genericQuestions pins", () => {
  it("the djb2×33 rotation picks the exact pool slot per date", async () => {
    const { genericQuestionForDate } = await import("../src/genericQuestions");
    // 2026-09-17: the pool grew 8 -> 60, so the same djb2 rotation lands
    // on new slots — recomputed against the shipped pool (the parity test
    // pins the pool itself array-for-array).
    expect(genericQuestionForDate("2026-09-07")).toBe("What did you get through today that felt heavy?");
    expect(genericQuestionForDate("2026-09-08")).toBe("What conversation stayed with you today?");
    expect(genericQuestionForDate("2026-10-01")).toBe("When did you feel understood today?");
  });
});

describe("kdf and envelope pins", () => {
  it("deriveMasterKeyAsync accepts an exactly-8-byte salt (both floors inclusive)", async () => {
    const master = await deriveMasterKeyAsync("pw", Buffer.alloc(8, 1), MIN_ITERATIONS);
    expect(master).toHaveLength(32);
    expect(master.equals(await deriveMasterKeyAsync("pw", Buffer.alloc(8, 1), MIN_ITERATIONS))).toBe(true);
  });

  it("a supplied nonce of the wrong length fails with the exact message", () => {
    const key = Buffer.alloc(32, 1);
    // 2026-09-16: the seam moved out of encrypt() — the production
    // signature takes exactly (key, plaintext, aad) and randomizes the
    // nonce; only encryptWithFixedNonce accepts one (red-team finding A5).
    expect(encrypt.length).toBe(3);
    expect(encryptWithFixedNonce.length).toBe(4);
    expect(() => encryptWithFixedNonce(key, Buffer.from("x"), undefined, Buffer.alloc(11))).toThrow(/nonce must be 12 bytes/);
    expect(() => encryptWithFixedNonce(key, Buffer.from("x"), undefined, Buffer.alloc(13))).toThrow(/nonce must be 12 bytes/);
  });
});

