/**
 * Deep-mutation pins for the shared components (2026-09-15 Stryker campaign):
 * buttons.tsx (PrimaryButton / GhostButton / CrisisHelpButton) and
 * InlineStatus.tsx (InlineStatus / NoticeChip).
 *
 * Every survivor is pinned by asserting the EXACT style array on the
 * TouchableOpacity / View / Text node it belongs to — including the literal
 * `false` entries the `&&` overlays produce — plus the accessibility-label
 * routing (`??` vs `&&`) and InlineStatus's null-message / tone gates.
 */
// @ts-nocheck

import { describe, expect, it, vi } from "vitest";
import React from "react";
import { ActivityIndicator, Text, TouchableOpacity, View } from "react-native";

const { PrimaryButton, GhostButton, CrisisHelpButton } = await import("../src/components/buttons");
const { InlineStatus, NoticeChip } = await import("../src/components/InlineStatus");
const { render, textOf, touchableByLabel } = await import("./helpers/rtr");

describe("PrimaryButton pins: the exact style-array contract", () => {
  it("enabled: primary base + fill overlay + the literal false (NO dimmed entry)", async () => {
    const root = await render(<PrimaryButton label="Save entry" onPress={() => {}} />);
    const btn = touchableByLabel(root, "Save entry");
    expect(btn.props.style).toEqual([
      { borderRadius: 10, padding: 16, alignItems: "center", justifyContent: "center" },
      { backgroundColor: "#3b5bdb", minHeight: 44 },
      false,
    ]);
  });

  it("busy: the dimmed overlay {opacity: 0.6} is the third array entry", async () => {
    const root = await render(<PrimaryButton label="Save entry" onPress={() => {}} busy />);
    const btn = root.root.findAllByType(TouchableOpacity)[0];
    expect(btn.props.style).toEqual([
      { borderRadius: 10, padding: 16, alignItems: "center", justifyContent: "center" },
      { backgroundColor: "#3b5bdb", minHeight: 44 },
      { opacity: 0.6 },
    ]);
    expect(root.root.findAllByType(ActivityIndicator)).toHaveLength(1);
  });

  it("disabled: dimmed too (the overlay keys off isDisabled, not just busy)", async () => {
    const root = await render(<PrimaryButton label="Save entry" onPress={() => {}} disabled />);
    const btn = root.root.findAllByType(TouchableOpacity)[0];
    expect((btn.props.style as unknown[])[2]).toEqual({ opacity: 0.6 });
    expect(btn.props.disabled).toBe(true);
  });
});

describe("GhostButton pins: centering, touch target, label routing", () => {
  it("default center=true: ghost base + centered + minHeight in order", async () => {
    const root = await render(<GhostButton label="Switch mode" onPress={() => {}} />);
    const btn = touchableByLabel(root, "Switch mode");
    expect(btn.props.style).toEqual([{ padding: 12 }, { alignItems: "center" }, { minHeight: 44 }]);
    // The default accessibilityLabel IS the visible label (?? routing).
    expect(btn.props.accessibilityLabel).toBe("Switch mode");
  });

  it("center={false}: the centered entry is the literal false, never the style", async () => {
    const root = await render(<GhostButton label="Support resources" onPress={() => {}} center={false} />);
    const btn = touchableByLabel(root, "Support resources");
    expect(btn.props.style).toEqual([{ padding: 12 }, false, { minHeight: 44 }]);
  });

  it("an explicit accessibilityLabel overrides the visible label (??, not &&)", async () => {
    const root = await render(
      <GhostButton label="Get help" onPress={() => {}} accessibilityLabel="Get help — crisis resources" />,
    );
    expect(touchableByLabel(root, "Get help").props.accessibilityLabel).toBe("Get help — crisis resources");
  });
});

describe("CrisisHelpButton pins", () => {
  it("the help surface and its label text carry their exact styles", async () => {
    const root = await render(<CrisisHelpButton onPress={() => {}} />);
    const btn = touchableByLabel(root, "Need help now? Crisis resources");
    expect(btn.props.style).toEqual([
      { padding: 16, alignItems: "center", justifyContent: "center" },
      { backgroundColor: "#242a38", borderRadius: 10, minHeight: 44 },
    ]);
    const label = root.root.findAllByType(Text)[0];
    expect(label.props.style).toEqual([{ fontWeight: "700" }, { color: "#e8eaf0", fontSize: 14 }]);
  });
});

describe("InlineStatus pins", () => {
  it("a null message renders nothing at all — not even a View", async () => {
    const empty = await render(<InlineStatus message={null} />);
    expect(empty.root.findAllByType(View)).toHaveLength(0);
    expect(empty.root.findAllByType(Text)).toHaveLength(0);
    expect(textOf(empty)).toBe("");
  });

  it("the status line: exact surface array and the DEFAULT ok tone's success color", async () => {
    const root = await render(<InlineStatus message="Saved ✓" />);
    const view = root.root.findAll((n) => n.props.accessibilityLiveRegion === "polite")[0];
    expect(view).toBeDefined();
    expect(view.props.style).toEqual([
      { paddingVertical: 10, paddingHorizontal: 14, alignItems: "center" },
      { backgroundColor: "#141821", borderRadius: 10 },
    ]);
    // tone defaults to "ok" → success color (a "" default or a false tone
    // condition would render the neutral muted color instead).
    expect(root.root.findAllByType(Text)[0].props.style).toEqual({ color: "#59c98a", fontSize: 13 });
  });

  it("the neutral tone renders the muted color exactly", async () => {
    const root = await render(<InlineStatus message="Saved — will sync when online" tone="neutral" />);
    expect(root.root.findAllByType(Text)[0].props.style).toEqual({ color: "#8a91a3", fontSize: 13 });
  });
});

describe("NoticeChip pins", () => {
  it("the chip surface and its text carry their exact styles", async () => {
    const root = await render(<NoticeChip text="Draft restored" />);
    const view = root.root.findAll((n) => n.props.accessibilityRole === "text")[0];
    expect(view).toBeDefined();
    expect(view.props.style).toEqual([
      { alignSelf: "flex-start", paddingVertical: 6, paddingHorizontal: 12 },
      { backgroundColor: "#1a1e26", borderRadius: 12 },
    ]);
    expect(root.root.findAllByType(Text)[0].props.style).toEqual({ color: "#8a91a3", fontSize: 12 });
  });
});

tests/crisisPhrases.test.ts.source:
/**
 * Parity + contract tests for the embedded crisis phrase lists.
 *
 * src/crisisPhrases.ts is an EMBEDDED COPY of shared/crisis_phrases.json
 * (Metro cannot import outside the project root — the same reason the
 * crypto vectors are verified by a node tool). This suite reads the shared
 * file from disk and pins:
 *   1. exact array parity for both tiers,
 *   2. every fixture in the shared contract (dialog_fires fire the dialog
 *      tier, dialog_silent do not, suppress_only_fires hit the suppress
 *      tier WITHOUT firing the dialog tier),
 *   3. the tier relationship: suppress = dialog + suppress_extra.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import { CRISIS_BENIGN_COMPOUNDS, CRISIS_DIALOG_PATTERNS, CRISIS_SUPPRESS_EXTRA_PATTERNS } from "../src/crisisPhrases";
import { detectCrisisLanguage, matchesCrisisSuppress } from "../src/crisisDetect";

const here = dirname(fileURLToPath(import.meta.url));
const shared = JSON.parse(readFileSync(join(here, "..", "..", "shared", "crisis_phrases.json"), "utf8")) as {
  v: number;
  dialog: string[];
  suppress_extra: string[];
  benign_compounds: string[];
  redteam_corpus: { technique: string; sample: string; intent: string; dialog: boolean; suppress: boolean }[];
  fixtures: { dialog_fires: string[]; dialog_silent: string[]; suppress_only_fires: string[] };
};

describe("shared/crisis_phrases.json parity", () => {
  it("embeds the dialog and suppress_extra lists exactly", () => {
    expect(shared.v).toBe(1);
    expect([...CRISIS_DIALOG_PATTERNS]).toEqual(shared.dialog);
    expect([...CRISIS_SUPPRESS_EXTRA_PATTERNS]).toEqual(shared.suppress_extra);
  });

  it("embeds the benign_compounds list exactly", () => {
    expect([...CRISIS_BENIGN_COMPOUNDS]).toEqual(shared.benign_compounds);
  });

  it("every pattern compiles under ECMAScript RegExp (the mobile engine)", () => {
    for (const pattern of [...CRISIS_DIALOG_PATTERNS, ...CRISIS_SUPPRESS_EXTRA_PATTERNS]) {
      expect(() => new RegExp(pattern, "i")).not.toThrow();
    }
  });
});

describe("red-team corpus (promoted 2026-09-17 from redteam/e_crisis.py)", () => {
  // Every row's dialog/suppress values are the REQUIRED contract. The
  // backend suite replays the identical rows against its engine — the two
  // must agree or the shared contract has drifted.
  it("every crisis sample hits the suppress tier (zero bypasses)", () => {
    const crisisRows = shared.redteam_corpus.filter((r) => r.intent === "crisis");
    expect(crisisRows.length).toBeGreaterThanOrEqual(30);
    for (const row of crisisRows) {
      expect(matchesCrisisSuppress(row.sample), `BYPASS: ${row.technique}: ${row.sample}`).toBe(true);
    }
  });

  it("observed verdicts match the contract exactly", () => {
    for (const row of shared.redteam_corpus) {
      expect(detectCrisisLanguage(row.sample), `dialog diverged on ${row.sample}`).toBe(row.dialog);
      expect(matchesCrisisSuppress(row.sample), `suppress diverged on ${row.sample}`).toBe(row.suppress);
    }
  });
});

describe("shared fixtures", () => {
  it.each(shared.fixtures.dialog_fires)("dialog tier fires on %j", (text) => {
    expect(detectCrisisLanguage(text)).toBe(true);
  });

  it.each(shared.fixtures.dialog_silent)("dialog tier stays silent on %j", (text) => {
    expect(detectCrisisLanguage(text)).toBe(false);
  });

  it.each(shared.fixtures.suppress_only_fires)("suppress tier (not dialog) fires on %j", (text) => {
    expect(matchesCrisisSuppress(text)).toBe(true);
    expect(detectCrisisLanguage(text)).toBe(false);
  });
});

describe("tier relationship", () => {
  it("the suppress tier is a strict superset of the dialog tier", () => {
    // Every dialog hit is necessarily a suppress hit.
    for (const text of [...shared.fixtures.dialog_fires, ...shared.fixtures.suppress_only_fires]) {
      if (detectCrisisLanguage(text)) expect(matchesCrisisSuppress(text)).toBe(true);
    }
  });

  it("broad everyday text hits neither tier", () => {
    expect(matchesCrisisSuppress("Had a good day. Walked the dog, called mom.")).toBe(false);
    expect(matchesCrisisSuppress("the exam was brutal")).toBe(false);
  });
});

tests/redteamFixes2026.test.ts.source:
/**
 * Regression pins for the 2026-09-16 red-team remediation wave
 * (reports/redteam_audit_2026-09-16.md), mobile side. The obfuscation
 * corpus for crisis detection is pinned cross-engine by the shared JSON
 * fixtures (crisisPhrases.test.ts replays them); these tests cover the
 * fixes that are mobile-only behavior.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";
import AsyncStorage from "@react-native-async-storage/async-storage";

import { normalizeCrisisText } from "../src/crisisDetect";
import { KDF_ITERATIONS, MIN_ITERATIONS, deriveMasterKey, deriveMasterKeyAsync } from "../src/crypto/kdf";
import { encrypt } from "../src/crypto/envelope";
import { detailToMessage, api } from "../src/api/client";

beforeEach(() => {
  (AsyncStorage as unknown as { __reset(): void }).__reset();
});

describe("A4: KDF iteration floor (client side)", () => {
  it("refuses to derive below MIN_ITERATIONS", () => {
    const salt = Buffer.alloc(16, 7);
    expect(() => deriveMasterKey("pw", salt, 1)).toThrow(/iterations must be at least/);
    expect(() => deriveMasterKey("pw", salt, MIN_ITERATIONS - 1)).toThrow(/iterations must be at least/);
  });

  it("still derives at the floor and at the production default", async () => {
    const salt = Buffer.alloc(16, 7);
    expect(deriveMasterKey("pw", salt, MIN_ITERATIONS).length).toBe(32);
    expect((await deriveMasterKeyAsync("pw", salt, MIN_ITERATIONS)).length).toBe(32);
    expect(KDF_ITERATIONS).toBe(600_000);
    expect(MIN_ITERATIONS).toBeGreaterThanOrEqual(100_000);
  });
});

describe("A5: production encrypt() has no nonce parameter", () => {
  it("always randomizes (two calls differ)", () => {
    const key = Buffer.alloc(32, 3);
    expect(encrypt(key, Buffer.from("x"))).not.toEqual(encrypt(key, Buffer.from("x")));
  });
});

describe("E1: crisis normalization engine (mobile side)", () => {
  it("folds leetspeak, homoglyphs, invisible chars and separators", () => {
    expect(normalizeCrisisText("Ѕuіϲіde​ thoughts…")).toBe("suicide thoughts");
    expect(normalizeCrisisText("s.u.i.c.i.d.e")).toBe("suicide");
    expect(normalizeCrisisText("s u i c i d e")).toBe("suicide");
    expect(normalizeCrisisText("k1ll myself")).toBe("kill myself");
    expect(normalizeCrisisText("su­icide")).toBe("suicide");
    expect(normalizeCrisisText("1 want to d1e so bad")).toBe("1 want to die so bad");
  });

  it("does not eat ordinary prose", () => {
    expect(normalizeCrisisText("i am so sad today")).toBe("i am so sad today");
    expect(normalizeCrisisText("to be or not to be that is the question")).toBe(
      "to be or not to be that is the question",
    );
    expect(normalizeCrisisText("u s a won gold")).toBe("u s a won gold");
  });

  it("is idempotent", () => {
    const once = normalizeCrisisText("Ѕuіϲіde​ thoughts…");
    expect(normalizeCrisisText(once)).toBe(once);
  });

  it("passes unmapped characters in the homoglyph ranges through untouched", () => {
    // б г д ж ц ш щ have no Latin lookalike mapping — they must survive
    // (only the confusable subset folds).
    expect(normalizeCrisisText("бгдж цшщ")).toBe("бгдж цшщ");
  });

  it("keeps non-latin single-letter tokens unjoined", () => {
    // Digits and CJK singles never enter the latin join rule.
    expect(normalizeCrisisText("5 五 x ray")).toBe("5 五 x ray");
  });

  it("folds chained leet digits through repeated passes", () => {
    expect(normalizeCrisisText("un4l1ve myself")).toBe("unalive myself");
    expect(normalizeCrisisText("no leet here at all")).toBe("no leet here at all");
  });
});

describe("F2: error-dialog sanitizer (scheme-less domains, phone digits)", () => {
  it("strips bare domains and phone-like digit runs", () => {
    expect(detailToMessage("go to evil.com/support for help", 400)).not.toContain("evil.com");
    expect(detailToMessage("call 555-0134 now", 400)).not.toContain("555");
    expect(detailToMessage("see https://evil.example/x", 400)).not.toContain("evil");
    expect(detailToMessage("open mindpattern-support://x", 400)).not.toContain("://");
  });

  it("keeps ordinary messages readable", () => {
    const out = detailToMessage("username is taken; try another in 5 minutes", 409);
    expect(out).toContain("username is taken");
    expect(out).toContain("5 minutes");
  });
});

describe("F2: the data key never rides plain HTTP", () => {
  it("openProcessingSession refuses a consented insecure URL before any fetch", async () => {
    await AsyncStorage.setItem("@mindpattern/base_url", "http://attacker.example");
    await AsyncStorage.setItem("@mindpattern/insecure_http_ok", "http://attacker.example");
    const spy = vi.fn();
    vi.stubGlobal("fetch", spy);
    try {
      await expect(
        api.openProcessingSession(Buffer.alloc(32, 9).toString("base64")),
      ).rejects.toThrow(/HTTPS/);
      expect(spy).not.toHaveBeenCalled();
    } finally {
      vi.unstubAllGlobals();
    }
  });

  it("allows loopback http (local development servers)", async () => {
    await AsyncStorage.setItem("@mindpattern/base_url", "http://localhost:8000");
    const spy = vi.fn(async () => ({
      ok: true,
      status: 201,
      url: "http://localhost:8000/api/v1/processing/sessions",
      headers: new Headers({ "Content-Type": "application/json" }),
      json: async () => ({ session_token: "st", expires_in: 300 }),
    }));
    vi.stubGlobal("fetch", spy);
    try {
      const out = await api.openProcessingSession(Buffer.alloc(32, 9).toString("base64"));
      expect(out.session_token).toBe("st");
      expect(spy).toHaveBeenCalled();
    } finally {
      vi.unstubAllGlobals();
    }
  });
});

tests/readableExport.test.ts.source:
/**
 * Readable journal export (2026-09-17): the human-readable Markdown copy
 * next to the encrypted backup. Pins the document format, on-device
 * decryption (never plaintext over the network), and the skip-counting of
 * undecryptable blobs.
 */
import { beforeEach, describe, expect, it, vi } from "vitest";

const apiMock = vi.hoisted(() => ({
  getUserId: vi.fn(),
  listEntries: vi.fn(),
}));

vi.mock("../src/api/client", () => ({ api: apiMock }));
// Real crypto path: encrypt fixtures with the app's own envelope so the
// decrypt side is the shipping code.
const { encryptEntry } = await import("../src/crypto/MindPatternCrypto");
const { vault } = await import("../src/vault");
const { buildReadableExport, MAX_READABLE_CHARS, moodWord } = await import("../src/readableExport");

const DATA_KEY = Buffer.alloc(32, 7);
const USER = "user-1";

function encryptedEntry(text: string, date: string, sentiment: number | null, id: string): string {
  return encryptEntry({ dataKey: DATA_KEY }, USER, id, text, date, sentiment).blobB64;
}

beforeEach(() => {
  apiMock.getUserId.mockResolvedValue(USER);
  apiMock.listEntries.mockReset();
  vault.unlock({ masterKey: Buffer.alloc(32), authKey: Buffer.alloc(32, 1), dataKey: DATA_KEY }, USER);
});

describe("buildReadableExport", () => {
  it("renders oldest-first Markdown with dates, text, and mood lines", async () => {
    apiMock.listEntries.mockResolvedValue([
      // newest first (server order) — the document reverses it
      { id: "2", client_entry_id: "e2", blob: encryptedEntry("second day calm", "2026-09-02", 0.5, "e2"), entry_date: "2026-09-02", received_at: "2026-09-02T10:00:00Z" },
      { id: "1", client_entry_id: "e1", blob: encryptedEntry("first day heavy", "2026-09-01", -0.8, "e1"), entry_date: "2026-09-01", received_at: "2026-09-01T10:00:00Z" },
    ]);
    const out = await buildReadableExport(new Date("2026-09-17T00:00:00Z"));
    expect(out.entryCount).toBe(2);
    expect(out.skippedCount).toBe(0);
    const first = out.markdown.indexOf("first day heavy");
    const second = out.markdown.indexOf("second day calm");
    expect(first).toBeGreaterThan(-1);
    expect(second).toBeGreaterThan(first); // oldest first
    expect(out.markdown).toContain("# MindPattern journal");
    expect(out.markdown).toContain("## 2026-09-01");
    expect(out.markdown).toContain("_mood: Heavy_");
    expect(out.markdown).toContain("_mood: Good_");
    expect(out.markdown).toContain("2 entries");
  });

  it("skips undecryptable blobs and counts them honestly", async () => {
    apiMock.listEntries.mockResolvedValue([
      { id: "1", client_entry_id: "e1", blob: encryptedEntry("good", "2026-09-01", null, "e1"), entry_date: "2026-09-01", received_at: "x" },
      { id: "2", client_entry_id: "e2", blob: Buffer.from("garbage").toString("base64"), entry_date: "2026-09-02", received_at: "x" },
    ]);
    const out = await buildReadableExport();
    expect(out.entryCount).toBe(1);
    expect(out.skippedCount).toBe(1);
    expect(out.markdown).toContain("1 entry could not be decrypted");
    expect(out.markdown).not.toContain("garbage");
  });

  it("caps a valid oversized journal deterministically before the share sheet", async () => {
    const oversized = "x".repeat(MAX_READABLE_CHARS);
    apiMock.listEntries.mockResolvedValue([
      { id: "1", client_entry_id: "e1", blob: encryptedEntry(oversized, "2026-09-01", null, "e1"), entry_date: "2026-09-01", received_at: "x" },
    ]);

    const out = await buildReadableExport();

    expect(out.entryCount).toBe(0);
    expect(out.skippedCount).toBe(0);
    expect(out.truncatedCount).toBe(1);
    expect(out.markdown.length).toBeLessThanOrEqual(MAX_READABLE_CHARS);
    expect(out.markdown).toContain("1 entry omitted to keep this export under 4 MB");
  });

  it("fails loudly without a user id (never exports an empty shell)", async () => {
    apiMock.getUserId.mockResolvedValue(null);
    await expect(buildReadableExport()).rejects.toThrow("account id missing");
  });

  it("entries without a mood pick render with no mood line", async () => {
    apiMock.listEntries.mockResolvedValue([
      { id: "1", client_entry_id: "e1", blob: encryptedEntry("plain", "2026-09-01", null, "e1"), entry_date: "2026-09-01", received_at: "x" },
    ]);
    const out = await buildReadableExport();
    expect(out.markdown).not.toContain("_mood:");
  });
});

describe("moodWord", () => {
  it("maps the 5-point check-in scale to its labels", () => {
    expect(moodWord(-1)).toBe("Heavy");
    expect(moodWord(-0.5)).toBe("Low");
    expect(moodWord(0)).toBe("Okay");
    expect(moodWord(0.5)).toBe("Good");
    expect(moodWord(1)).toBe("Light");
    expect(moodWord(null)).toBeNull();
    expect(moodWord(undefined)).toBeNull();
    expect(moodWord(Number.NaN)).toBeNull();
  });
});

