/**
 * The sharing methods of the real api client (fetch stubbed globally, per
 * client.request.test.ts): wire shapes, verifier transport, and the
 * consent-id URL-path guard.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import storage from "./helpers/storageMock";
import { api, ApiError, DEFAULT_BASE_URL, SHARING_DISCLOSURE_VERSION } from "../src/api/client";

const jsonResponse = (body: unknown, status = 200, url = DEFAULT_BASE_URL): Response => {
  const response = new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json" } });
  Object.defineProperty(response, "url", { value: url });
  return response;
};

beforeEach(() => {
  storage.__reset();
  vi.stubGlobal("fetch", vi.fn(async () => jsonResponse({ ok: true })));
});

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("sharing client methods", () => {
  it("pairingLookup posts the code (never in the URL path)", async () => {
    await api.pairingLookup("ab2c4d6f");
    const [url, init] = (globalThis.fetch as ReturnType<typeof vi.fn>).mock.calls[0] as [
      string,
      RequestInit,
    ];
    expect(url).toBe(`${DEFAULT_BASE_URL}/api/v1/consents/pairing/lookup`);
    expect(init.method).toBe("POST");
    expect(JSON.parse(init.body as string)).toEqual({ code: "ab2c4d6f" });
  });

  it("grantConsent ships the wrap + disclosure with the verifier header", async () => {
    await api.grantConsent("AB2C4D6F", "EPH", "WRAPPED", "verifier-b64");
    const [url, init] = (globalThis.fetch as ReturnType<typeof vi.fn>).mock.calls[0] as [
      string,
      RequestInit,
    ];
    expect(url).toBe(`${DEFAULT_BASE_URL}/api/v1/consents`);
    expect(init.method).toBe("POST");
    expect(init.headers).toMatchObject({ "X-Account-Verifier": "verifier-b64" });
    expect(JSON.parse(init.body as string)).toEqual({
      code: "AB2C4D6F",
      ephemeral_pub: "EPH",
      wrapped_key: "WRAPPED",
      disclosure: SHARING_DISCLOSURE_VERSION,
    });
    expect(SHARING_DISCLOSURE_VERSION).toBe("v1");
  });

  it("listConsents GETs the consent list", async () => {
    await api.listConsents();
    const [url, init] = (globalThis.fetch as ReturnType<typeof vi.fn>).mock.calls[0] as [
      string,
      RequestInit,
    ];
    expect(url).toBe(`${DEFAULT_BASE_URL}/api/v1/consents`);
    expect(init.method).toBe("GET");
  });

  it("revokeConsent DELETEs with the verifier header", async () => {
    const id = "a".repeat(32);
    await api.revokeConsent(id, "verifier-b64");
    const [url, init] = (globalThis.fetch as ReturnType<typeof vi.fn>).mock.calls[0] as [
      string,
      RequestInit,
    ];
    expect(url).toBe(`${DEFAULT_BASE_URL}/api/v1/consents/${id}`);
    expect(init.method).toBe("DELETE");
    expect(init.headers).toMatchObject({ "X-Account-Verifier": "verifier-b64" });
  });

  it("refuses a tampered consent id before any request ships", async () => {
    await expect(api.revokeConsent("../../account", "v")).rejects.toMatchObject({
      status: 0,
      name: "ApiError",
    });
    expect((globalThis.fetch as ReturnType<typeof vi.fn>).mock.calls).toHaveLength(0);
    // The refusal is a local ApiError, not a thrown string.
    await api.revokeConsent("short").catch((err: unknown) => {
      expect(err).toBeInstanceOf(ApiError);
    });
  });

  it("surfaces a revoked-patient 404 as a not-found ApiError", async () => {
    vi.stubGlobal(
      "fetch",
      vi.fn(async () => jsonResponse({ detail: "consent not found", code: "not_found" }, 404)),
    );
    await expect(api.revokeConsent("b".repeat(32), "v")).rejects.toMatchObject({
      status: 404,
      code: "not_found",
    });
  });
});

tests/components.bottomNav.test.tsx.source:
/**
 * BottomNav + MainShell: the persistent navigation (2026-09-17).
 *
 * Pins: all six destinations always render (crisis help is one tap from
 * every main screen — the navigation contract), the active tab carries
 * selection state, taps navigate, and the bar's styling matches the
 * design system.
 */
import React from "react";
import { describe, expect, it, vi } from "vitest";

const navigate = vi.fn();

const { BottomNav, BOTTOM_NAV_ITEMS, MainShell } = await import("../src/components/BottomNav");
const { Text } = await import("react-native");
const { render, textOf, touchableByLabel, pressLabel } = await import("./helpers/rtr");

describe("BottomNav", () => {
  it("always renders all six destinations, Get help last", async () => {
    const labels = BOTTOM_NAV_ITEMS.map((i) => i.label);
    expect(labels).toEqual(["Today", "History", "Patterns", "Question", "Settings", "Get help"]);
    const root = await render(<BottomNav current="Entry" navigation={{ navigate }} />);
    for (const label of labels) {
      expect(textOf(root)).toContain(label);
    }
  });

  it("marks the current destination selected (accessibility tab state)", async () => {
    const root = await render(<BottomNav current="History" navigation={{ navigate }} />);
    expect(touchableByLabel(root, "History").props.accessibilityState).toEqual({ selected: true });
    expect(touchableByLabel(root, "Patterns").props.accessibilityState).toBeUndefined();
  });

  it("navigates on tap", async () => {
    const root = await render(<BottomNav current="Entry" navigation={{ navigate }} />);
    await pressLabel(root, "Patterns");
    expect(navigate).toHaveBeenCalledWith("Insights");
    touchableByLabel(root, "Get help").props.onPress();
    expect(navigate).toHaveBeenCalledWith("Crisis");
  });

  it("the help action keeps its distinct surface and weight", async () => {
    const { allStyles } = await import("./helpers/rtr");
    const root = await render(<BottomNav current="none" navigation={{ navigate }} />);
    expect(allStyles(root).some((s) => s.backgroundColor === "#242a38")).toBe(true); // helpBg
  });

  it("current='none' selects nothing", async () => {
    const root = await render(<BottomNav current="none" navigation={{ navigate }} />);
    expect(textOf(root)).toContain("Today"); // renders without selection
    expect(touchableByLabel(root, "Today").props.accessibilityState).toBeUndefined();
  });
});

describe("MainShell", () => {
  it("renders children above the persistent bar", async () => {
    const root = await render(
      <MainShell current="Settings" navigation={{ navigate }}>
        <Text>screen content</Text>
      </MainShell>,
    );
    expect(textOf(root)).toContain("screen content");
    expect(textOf(root)).toContain("Today");
    expect(textOf(root)).toContain("Settings");
  });
});

tests/crisisDetect.test.ts.source:
/**
 * crisisDetect: the on-device, pre-encryption crisis-language matcher.
 * Pins every phrase family (a silent regression here means a missed
 * crisis), the case/whitespace tolerance of quick typing, and — just as
 * important — that everyday journal text does NOT trip it.
 */
import { describe, expect, it } from "vitest";
import { detectCrisisLanguage, matchVariants, normalizeCrisisText } from "../src/crisisDetect";

describe("detectCrisisLanguage — true positives", () => {
  it.each([
    // Direct suicidal statements (each phrase family).
    "I keep thinking about how to kill myself",
    "i have been thinking about killing myself",
    "the note mentioned suicide twice",
    "I feel suicidal tonight",
    "I want to die",
    "i wanted to die back then",
    "I just wanna die sometimes",
    "I wish I was dead",
    "I wish i were dead",
    // Ending it.
    "I just want to end it all",
    "thinking about ending it all",
    "I want to end my life",
    "plans for ending my life",
    "thinking about how to take my own life",
    "afraid I will take my life",
    // Self-harm.
    "I keep slipping back into self harm",
    "the self-harm started again",
    "i am self harming again",
    "I want to hurt myself",
    "I keep hurting myself",
    // Hopelessness phrases.
    "there is no reason to live anymore",
    "no reason to go on",
    "I can't go on like this",
    "i cant go on",
    "I cannot go on anymore",
    "everyone would be better off without me",
    "I don't want to be here",
    "i dont want to live",
    "I do not want to exist",
    // M2 additions: purpose-in-life, be-alive, death-wish gerunds/infinitives,
    // and the cut-myself self-harm family.
    "there is nothing to live for",
    "i have nothing to live for anymore",
    "I don't want to be alive",
    "i do not want to be alive",
    "wanting to die more days than not",
    "i keep wanting to die",
    "i feel like dying",
    "lately everything feels like dying inside",
    "wish i could die",
    "I wish I could die in my sleep",
    "i cut myself again",
    "i have been cutting myself",
  ])("fires on %j", (text) => {
    expect(detectCrisisLanguage(text)).toBe(true);
  });

  // iOS Smart Punctuation substitutes U+2019 for ASCII ' by default — every
  // apostrophe-tolerant family must fire on BOTH spellings or iPhone typing
  // silently misses detection.
  const CURLY = "\u2019";
  it.each([
    `I can${CURLY}t go on`,
    `i don${CURLY}t want to live`,
    `I don${CURLY}t want to be here`,
    `don${CURLY}t want to be alive`,
    `i don${CURLY}t want to exist`,
  ])("fires on the curly-apostrophe (U+2019) variant %j", (text) => {
    expect(detectCrisisLanguage(text)).toBe(true);
  });

  it("still fires on the ASCII and dropped-apostrophe variants", () => {
    expect(detectCrisisLanguage("I can't go on")).toBe(true);
    expect(detectCrisisLanguage("i cant go on")).toBe(true);
    expect(detectCrisisLanguage("I cannot go on")).toBe(true);
    expect(detectCrisisLanguage("i dont want to live")).toBe(true);
    expect(detectCrisisLanguage("I do not want to live")).toBe(true);
  });

  it("is case-insensitive, including ALL CAPS and mixed case", () => {
    expect(detectCrisisLanguage("I WANT TO DIE")).toBe(true);
    expect(detectCrisisLanguage("I wAnT tO eNd It AlL")).toBe(true);
    expect(detectCrisisLanguage("SUICIDAL")).toBe(true);
  });

  it("fires when the phrase is buried in a longer entry", () => {
    const entry =
      "Work was fine and the kids were sweet at dinner, but if I am honest " +
      "with myself I keep coming back to the thought that they would be " +
      "better off without me. I will try to sleep now.";
    expect(detectCrisisLanguage(entry)).toBe(true);
  });

  it("tolerates extra whitespace and newlines inside phrases", () => {
    expect(detectCrisisLanguage("I want  to\n die")).toBe(true);
    expect(detectCrisisLanguage("no  reason\tto live")).toBe(true);
  });
});

describe("detectCrisisLanguage — true negatives", () => {
  it.each([
    // Ordinary journal text.
    "Had a good day. Walked the dog, finished the report, called mom.",
    "The assessment at work was brutal but I passed it.",
    "That workout killed my legs — I can barely walk.",
    "This traffic is killing me.",
    "My boss would kill me if I missed that deadline.",
    "I was dying of laughter at the show.",
    "I'm dead tired after the red-eye.",
    "I killed it at the presentation today.",
    "Feeling anxious about the move but also excited.",
    "I want to diet again starting Monday.",
    "The exam ends, it all comes down to Friday.",
    // Near-misses for the M2 additions.
    "I have nothing to lose.",
    "the new hire has nothing to live up to",
    "i do want to be alive",
    "i want to be alive for my kids",
    "I wish I could fly",
    "feels like a dying art form",
    "i need to cut my hair this weekend",
    "his cutting remarks stung all day",
  ])("does NOT fire on %j", (text) => {
    expect(detectCrisisLanguage(text)).toBe(false);
  });

  it("stays silent on benign compounds (masked since 2026-09-17): titles and campaigns", () => {
    // "suicide squad"/"suicide prevention"/... are masked from both tiers —
    // the bare topic word inside them is not first-person ideation. Every
    // OTHER use of the word still fires (see the true-positive block).
    expect(detectCrisisLanguage("We discussed suicide prevention policy in class today.")).toBe(false);
    expect(detectCrisisLanguage("that movie was suicide squad and i liked it")).toBe(false);
    expect(detectCrisisLanguage("listening to suicide silence again")).toBe(false);
  });

  it("still fires on the word 'suicide' outside the benign compounds", () => {
    expect(detectCrisisLanguage("thinking about suicide again")).toBe(true);
    expect(detectCrisisLanguage("the suicide prevention lecture left me suicidal")).toBe(true);
  });

  it("accepts the documented false positives: benign 'cut myself' / 'feel like dying' contexts", () => {
    // A clean context distinction ("shaving", "chopping onions", gym
    // hyperbole) would be an incomplete blocklist pretending to be
    // precision — see the crisisDetect header. The conservative contract
    // pays one gentle dialog instead of risking a miss.
    expect(detectCrisisLanguage("I cut myself shaving this morning")).toBe(true);
    expect(detectCrisisLanguage("I feel like dying after that workout")).toBe(true);
  });

  it("does not fire on empty or whitespace-only input", () => {
    expect(detectCrisisLanguage("")).toBe(false);
    expect(detectCrisisLanguage("   \n\t  ")).toBe(false);
  });

  it("does not fire on partial-word lookalikes", () => {
    expect(detectCrisisLanguage("the assessment was nothing relevant")).toBe(false);
    expect(detectCrisisLanguage("a dying breed of craftsman")).toBe(false);
    expect(detectCrisisLanguage("the suicidology textbook")).toBe(false);
  });
});

describe("dual-variant matching + benign masking (2026-09-17)", () => {
  it("fires on partial-split evasion: orphan single letters glue onto the next word", () => {
    // The documented "k ill myself" residual bypass, now closed on both engines.
    expect(detectCrisisLanguage("k ill myself")).toBe(true);
    expect(detectCrisisLanguage("o ff myself tonight")).toBe(true);
    expect(detectCrisisLanguage("k i ll myself")).toBe(true);
    expect(detectCrisisLanguage("s uicide is on my mind")).toBe(true);
  });

  it("the orphan variant never manufactures matches from ordinary prose", () => {
    expect(detectCrisisLanguage("i am so sad today")).toBe(false);
    expect(detectCrisisLanguage("i want to diet")).toBe(false);
    expect(detectCrisisLanguage("u s a won gold")).toBe(false);
    expect(detectCrisisLanguage("a way out of the city")).toBe(false);
  });

  it("matchVariants returns the primary, orphan and concat forms, benign compounds masked in all three", () => {
    const [primary, orphan, concat] = matchVariants("k ill myself after that suicide squad movie");
    expect(primary).toBe("k ill myself after that movie");
    expect(orphan).toBe("kill myself after that movie"); // glued AND masked
    expect(concat).toBe("killmyselfafterthatmovie"); // concatenated AND masked
    // The mask runs pre-punctuation-fold: a comma between the compound's
    // words is NOT the compound, so real ideation survives (audit pin).
    const [p2] = matchVariants("thinking about suicide, silence and pain");
    expect(p2).toBe("thinking about suicide silence and pain");
  });

  it("the primary variant equals normalizeCrisisText on compound-free text", () => {
    const text = "s u i c i d e notes everywhere";
    expect(matchVariants(text)[0]).toBe(normalizeCrisisText(text));
  });
});

tests/moodLog.test.ts.source:
/**
 * The device-local mood log that powers the baseline-phase trend view.
 * Invariants: per-account isolation (by key AND by AAD), upsert-by-date,
 * clamped values, bounded history, streak grace — and, since the privacy
 * audit: the stored bytes are ENCRYPTED under the data key, a tampered or
 * wrong-key blob degrades to empty, and the legacy plaintext format
 * migrates transparently.
 */
import { beforeEach, describe, expect, it } from "vitest";
import storage from "./helpers/storageMock";

const { recordMood, recentMoods, localStreak, clearMoodLog, localDateISO } = await import("../src/moodLog");
const { buildAad, encrypt } = await import("../src/crypto/envelope");

const keyA = Buffer.alloc(32, 1);
const keyB = Buffer.alloc(32, 2);

const day = (offset: number): string => {
  const d = new Date(Date.UTC(2026, 8, 4 + offset));
  return d.toISOString().slice(0, 10);
};

const storedRaw = async (userId: string): Promise<string | null> =>
  storage.getItem(`mindpattern.moodlog.${userId}`);

beforeEach(() => {
  storage.__reset();
});

describe("moodLog", () => {
  it("records and returns days oldest-first", async () => {
    await recordMood(keyA, "u1", day(-2), -0.5);
    await recordMood(keyA, "u1", day(-1), 0.25);
    const moods = await recentMoods(keyA, "u1", 30);
    expect(moods.map((m) => m.value)).toEqual([-0.5, 0.25]);
  });

  it("stores ENCRYPTED bytes, never plaintext mood values", async () => {
    await recordMood(keyA, "u1", day(0), 0.66);
    const raw = await storedRaw("u1");
    expect(raw).not.toBeNull();
    expect(raw).not.toContain("0.66");
    expect(raw).not.toMatch(/^\[/); // not the legacy plaintext format
  });

  it("is AAD-bound: another account's key cannot read the log", async () => {
    await recordMood(keyA, "u1", day(0), 0.5);
    // Wrong key (different account): degrades to empty, never throws.
    expect(await recentMoods(keyB, "u1", 30)).toEqual([]);
  });

  it("isolates accounts by storage key", async () => {
    await recordMood(keyA, "u1", day(0), 0.5);
    expect(await recentMoods(keyA, "u2", 30)).toEqual([]);
  });

  it("a tampered blob degrades to empty, never throws", async () => {
    await recordMood(keyA, "u1", day(0), 0.5);
    const raw = (await storedRaw("u1")) as string;
    const flipped = raw.slice(0, -4) + (raw.endsWith("AAAA") ? "BBBB" : "AAAA");
    await storage.setItem("mindpattern.moodlog.u1", flipped);
    expect(await recentMoods(keyA, "u1", 30)).toEqual([]);
    expect(await localStreak(keyA, "u1", day(0))).toBe(0);
  });

  it("migrates the legacy plaintext format transparently", async () => {
    await storage.setItem(
      "mindpattern.moodlog.u1",
      JSON.stringify([{ date: day(-1), value: 0.3 }]),
    );
    const moods = await recentMoods(keyA, "u1", 30);
    expect(moods.map((m) => m.value)).toEqual([0.3]);
    // Next write re-stores the whole log encrypted.
    await recordMood(keyA, "u1", day(0), -0.2);
    const raw = await storedRaw("u1");
    expect(raw).not.toMatch(/^\[/);
    const all = await recentMoods(keyA, "u1", 30);
    expect(all.map((m) => m.value)).toEqual([0.3, -0.2]);
  });

  // M5: a read-only user (the Insights baseline view) must not keep a
  // plaintext mood log on disk forever — the read itself migrates it.
  it("read-through migration: a successful READ already re-stores encrypted bytes (M5)", async () => {
    await storage.setItem(
      "mindpattern.moodlog.u1",
      JSON.stringify([{ date: day(-1), value: 0.3 }]),
    );
    await recentMoods(keyA, "u1", 30); // read only — no write call from the caller
    const raw = await storedRaw("u1");
    expect(raw).not.toBeNull();
    expect(raw).not.toMatch(/^\[/); // no longer the legacy plaintext envelope
    expect(raw).not.toContain("0.3");
    // And the migrated ciphertext still decrypts to the same days.
    expect((await recentMoods(keyA, "u1", 30)).map((m) => m.value)).toEqual([0.3]);
  });

  it("a corrupt LEGACY blob degrades to empty instead of crashing the read", async () => {
    // Starts with "[" so the legacy path is taken, but the JSON is broken:
    // the parse failure must degrade to empty (and flag legacy for rewrite).
    await storage.setItem("mindpattern.moodlog.u1", "[{broken json");
    expect(await recentMoods(keyA, "u1", 30)).toEqual([]);
    expect(await localStreak(keyA, "u1", day(0))).toBe(0);
  });

  it("a decrypted payload that is not an array sanitizes to empty", async () => {
    // Valid AEAD, valid JSON — but the wrong SHAPE. Never render garbage.
    const notArray = encrypt(keyA, Buffer.from(JSON.stringify({ days: "lots" })), buildAad("moodlog", "u1"));
    await storage.setItem("mindpattern.moodlog.u1", notArray.toString("base64"));
    expect(await recentMoods(keyA, "u1", 30)).toEqual([]);
  });

  it("sanitize drops junk items from a legacy payload, keeping only valid days", async () => {
    await storage.setItem(
      "mindpattern.moodlog.u1",
      JSON.stringify([
        "junk",
        null,
        { date: "not-a-date", value: 0.1 },
        { date: "2026-09-01", value: "high" },
        { value: 0.4 },
        { date: "2026-09-02", value: 0.5 },
      ]),
    );
    expect(await recentMoods(keyA, "u1", 30)).toEqual([{ date: "2026-09-02", value: 0.5 }]);
  });

  it("upserts by date — one value per day", async () => {
    await recordMood(keyA, "u1", day(0), -0.5);
    await recordMood(keyA, "u1", day(0), 0.4);
    const moods = await recentMoods(keyA, "u1", 30);
    expect(moods).toHaveLength(1);
    expect(moods[0].value).toBe(0.4);
  });

  it("clamps out-of-range values", async () => {
    await recordMood(keyA, "u1", day(0), 7);
    const moods = await recentMoods(keyA, "u1", 30);
    expect(moods[0].value).toBe(1);
  });

  it("streak counts consecutive days ending today or yesterday", async () => {
    await recordMood(keyA, "u1", day(-3), 0.1);
    await recordMood(keyA, "u1", day(-2), 0.1);
    await recordMood(keyA, "u1", day(-1), 0.1);
    // Gap-free run ending yesterday → 3 (grace), not 0.
    expect(await localStreak(keyA, "u1", day(0))).toBe(3);
    await recordMood(keyA, "u1", day(0), 0.2);
    expect(await localStreak(keyA, "u1", day(0))).toBe(4);
  });

  it("streak breaks across a missed day", async () => {
    await recordMood(keyA, "u1", day(-4), 0.1);
    await recordMood(keyA, "u1", day(-2), 0.1); // gap at -3; nothing today or yesterday
    expect(await localStreak(keyA, "u1", day(0))).toBe(0);
  });

  it("corrupt storage degrades to empty, never throws", async () => {
    await storage.setItem("mindpattern.moodlog.u1", "{not json");
    expect(await recentMoods(keyA, "u1", 30)).toEqual([]);
    expect(await localStreak(keyA, "u1", day(0))).toBe(0);
  });

  it("clear removes everything for the account", async () => {
    await recordMood(keyA, "u1", day(0), 0.1);
    await clearMoodLog("u1");
    expect(await recentMoods(keyA, "u1", 30)).toEqual([]);
  });

  it("the AAD binds the log to the account id (regression for blob relocation)", async () => {
    // A log encrypted for u2 must not decrypt under u1's AAD even with the
    // right key — same anti-relocation property as entry blobs.
    const foreign = encrypt(keyA, Buffer.from(JSON.stringify([{ date: day(0), value: 0.9 }])), buildAad("moodlog", "u2"));
    await storage.setItem("mindpattern.moodlog.u1", foreign.toString("base64"));
    expect(await recentMoods(keyA, "u1", 30)).toEqual([]);
  });
});

describe("localDateISO", () => {
  // M9: entry dates and mood-log days must be the DEVICE-LOCAL calendar day;
  // toISOString().slice(0,10) is the UTC day and is wrong in the evening for
  // every non-UTC timezone.
  //
  // Pool note: these tests deliberately do NOT switch process.env.TZ. Under
  // vitest's `threads` pool (Stryker's vitest runner) the assignment never
  // reaches the process timezone — the Date getters stay on the ambient zone
  // and the east-of-UTC case deterministically fails there while passing
  // under the default `forks` pool. Instead, the expected day is derived
  // from getTimezoneOffset(): the SAME zone state the implementation's Date
  // getters read, so the assertion is valid under any ambient zone, any
  // pool, and any runner.
  const localDay = (d: Date): string =>
    new Date(d.getTime() - d.getTimezoneOffset() * 60_000).toISOString().slice(0, 10);

  it("returns the local calendar day of the ambient zone, not the UTC day", () => {
    // One instant early in the UTC day, one late: every non-UTC zone puts at
    // least one of the two on a local day different from its UTC day (west
    // of UTC shifts the early one back a day, east of UTC shifts the late
    // one forward), so the UTC-day rendering is rejected as wrong whenever
    // the machine is not on UTC.
    for (const ms of [Date.UTC(2026, 8, 4, 2, 30), Date.UTC(2026, 8, 3, 23, 30)]) {
      const d = new Date(ms);
      const utcDay = d.toISOString().slice(0, 10);
      expect(localDateISO(d)).toBe(localDay(d));
      if (localDay(d) !== utcDay) {
        expect(localDateISO(d)).not.toBe(utcDay);
      }
    }
  });

  it("zero-pads month and day", () => {
    expect(localDateISO(new Date(2026, 0, 5))).toBe("2026-01-05");
    expect(localDateISO(new Date(2026, 10, 20))).toBe("2026-11-20");
  });
});

describe("L6: recordMood serialization (no lost updates)", () => {
  it("two concurrent recordMood calls for different days both persist", async () => {
    const dataKey = Buffer.alloc(32, 4);
    await Promise.all([
      recordMood(dataKey, "u1", "2026-09-01", 0.5),
      recordMood(dataKey, "u1", "2026-09-02", -0.5),
    ]);
    const days = await recentMoods(dataKey, "u1", 30);
    expect(days.map((d) => d.date)).toEqual(["2026-09-01", "2026-09-02"]);
  });
});

describe("vault-lock race (zeroize mid-write)", () => {
  // recordMood is fire-and-forget with the vault's SHARED dataKey buffer.
  // The bug: backgrounding mid-await ran vault.lock(), zeroizing the
  // buffer, and the pending write encrypted under an all-zero key — the
  // next read failed GCM and the mood history silently reset to empty.
  it("a lock landing mid-record cannot corrupt the log (key is snapshotted at call time)", async () => {
    const liveDataKey = Buffer.alloc(32, 5); // stands in for the vault's buffer
    const originalBytes = Buffer.from(liveDataKey); // the test's own copy
    // Zeroize the shared buffer the moment the stored bytes have been read
    // — the worst possible interleaving for the pending write.
    const originalGetItem = storage.getItem.bind(storage);
    let armed = true;
    (storage as { getItem: typeof storage.getItem }).getItem = async (k: string) => {
      const value = await originalGetItem(k);
      if (armed && k === "mindpattern.moodlog.u1") {
        armed = false;
        liveDataKey.fill(0); // this is what vault.lock() does to the buffer
      }
      return value;
    };
    try {
      await recordMood(liveDataKey, "u1", "2026-09-01", 0.5);
    } finally {
      (storage as { getItem: typeof storage.getItem }).getItem = originalGetItem;
    }
    // The pending write encrypted under the SNAPSHOT, not the zeroed buffer:
    // the day is intact under the original key bytes...
    expect(await recentMoods(originalBytes, "u1", 30)).toEqual([{ date: "2026-09-01", value: 0.5 }]);
    // ...and the stored blob is definitely NOT under the all-zero key.
    expect(await recentMoods(Buffer.alloc(32), "u1", 30)).toEqual([]);
  });

  it("a lock mid-READ cannot produce a spurious empty trend", async () => {
    const liveDataKey = Buffer.alloc(32, 6);
    const originalBytes = Buffer.from(liveDataKey);
    await recordMood(originalBytes, "u1", "2026-09-01", 0.25);
    liveDataKey.fill(0); // locked between reads — the next call snapshots
    // A read after a lock simply sees the locked (zeroed) key: degrades to
    // empty, as any wrong key does — but the log itself is intact.
    expect(await recentMoods(liveDataKey, "u1", 30)).toEqual([]);
    expect(await recentMoods(originalBytes, "u1", 30)).toEqual([{ date: "2026-09-01", value: 0.25 }]);
  });
});

tests/theme.test.tsx.source:
/**
 * The theme is a product contract: the palettes themselves, the scales, and
 * — critically — the WCAG AA contrast commitments from the audit (the old
 * #5c6370 fine print measured 3.13:1; the old #4f7cff button measured
 * 3.71:1). The ratios below are computed from first principles (sRGB
 * relative luminance), not transcribed, so a palette edit that breaks AA
 * fails here loudly.
 */
import { describe, expect, it, vi } from "vitest";
import React from "react";
import { useColorScheme } from "react-native";

const { darkTheme, lightTheme, useTheme } = await import("../src/theme");
const { render } = await import("./helpers/rtr");

/** WCAG relative luminance of a #rrggbb color. */
function luminance(hex: string): number {
  const channel = (i: number): number => {
    const c = parseInt(hex.slice(i, i + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  };
  return 0.2126 * channel(1) + 0.7152 * channel(3) + 0.0722 * channel(5);
}

function contrast(fg: string, bg: string): number {
  const a = luminance(fg);
  const b = luminance(bg);
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}

/** Render the hook through a probe component and capture its result. */
async function probeTheme(): Promise<typeof darkTheme> {
  let captured: typeof darkTheme | null = null;
  function Probe(): null {
    captured = useTheme();
    return null;
  }
  await render(<Probe />);
  if (!captured) throw new Error("probe did not render");
  return captured;
}

describe("theme scales", () => {
  it("dark and light share one spacing/radius/type contract", () => {
    expect(darkTheme.spacing).toEqual(lightTheme.spacing);
    expect(darkTheme.radius).toEqual(lightTheme.radius);
    expect(darkTheme.type).toEqual(lightTheme.type);
    expect(darkTheme.minTouch).toBe(44);
    expect(darkTheme.spacing).toEqual({ xs: 4, sm: 8, md: 12, lg: 16, xl: 20, xxl: 24, xxxl: 32 });
    // The two palettes differ in every color except onPrimary (white labels
    // sit on fills that were each darkened until white passed AA).
    for (const key of Object.keys(darkTheme.colors) as (keyof typeof darkTheme.colors)[]) {
      if (key === "onPrimary") continue;
      expect(lightTheme.colors[key]).not.toBe(darkTheme.colors[key]);
    }
  });
});

describe("theme contrast (WCAG AA, computed)", () => {
  it("dark: muted fine print reaches 4.5:1 on both backgrounds", () => {
    expect(contrast(darkTheme.colors.muted, darkTheme.colors.bg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.muted, darkTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.muted, darkTheme.colors.cardDeep)).toBeGreaterThanOrEqual(4.5);
    // The audit's failing pair is the regression pin: 3.13:1 then, AA now.
    expect(contrast("#5c6370", "#0f1115")).toBeLessThan(4.5);
    expect(contrast(darkTheme.colors.muted, darkTheme.colors.bg)).toBeCloseTo(6.0, 0);
  });

  it("dark: button labels, body text, links and badges all pass on their surfaces", () => {
    expect(contrast(darkTheme.colors.onPrimary, darkTheme.colors.primary)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.onPrimary, darkTheme.colors.danger)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.body, darkTheme.colors.bg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.body, darkTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.text, darkTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.accent, darkTheme.colors.bg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.accent, darkTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.accent, darkTheme.colors.helpBg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.error, darkTheme.colors.bg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.success, darkTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(darkTheme.colors.text, darkTheme.colors.helpBg)).toBeGreaterThanOrEqual(4.5);
    // The old button pair is the second regression pin: 3.71:1 then.
    expect(contrast("#ffffff", "#4f7cff")).toBeLessThan(4.5);
  });

  it("light: the same promises hold on the light surfaces", () => {
    expect(contrast(lightTheme.colors.muted, lightTheme.colors.bg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.muted, lightTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.muted, lightTheme.colors.cardDeep)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.onPrimary, lightTheme.colors.primary)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.onPrimary, lightTheme.colors.danger)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.body, lightTheme.colors.bg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.body, lightTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.text, lightTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.accent, lightTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.accent, lightTheme.colors.helpBg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.error, lightTheme.colors.bg)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.success, lightTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.text, lightTheme.colors.helpBg)).toBeGreaterThanOrEqual(4.5);
  });

  it("placeholders meet the same 4.5:1 duty as muted text", () => {
    expect(contrast(darkTheme.colors.placeholder, darkTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
    expect(contrast(lightTheme.colors.placeholder, lightTheme.colors.card)).toBeGreaterThanOrEqual(4.5);
  });
});

describe("useTheme", () => {
  it("defaults to the dark palette and follows an explicit light scheme", async () => {
    vi.mocked(useColorScheme).mockReturnValue("dark");
    expect(await probeTheme()).toBe(darkTheme);

    vi.mocked(useColorScheme).mockReturnValue("light");
    expect(await probeTheme()).toBe(lightTheme);

    // An unrecognized value (or null) must never produce a broken theme:
    // calm default wins.
    vi.mocked(useColorScheme).mockReturnValue(null as never);
    expect(await probeTheme()).toBe(darkTheme);

    vi.mocked(useColorScheme).mockReturnValue("dark");
  });
});

tests/sharing.test.ts.source:
/**
 * Therapist-sharing wrap: the REAL shipping module (node engine behind the
 * same seam) against the cross-platform vectors in shared/vectors.json,
 * plus the negative space (wrong ids, malformed keys) vectors cannot
 * express.
 *
 * The vectors carry fixed TEST keys for both sides, so this file can run
 * the therapist side too (node:crypto directly): wrap with the patient
 * code, unwrap with the vector's private key, land back on the data key.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import nodeCrypto from "node:crypto";
import { describe, expect, it } from "vitest";

import { deriveWrapKek, wrapDataKeyForTherapist, WRAP_CONTEXT } from "../src/crypto/sharing";
import { buildAad, decrypt, encryptWithFixedNonce, TamperError } from "../src/crypto/envelope";

const here = dirname(fileURLToPath(import.meta.url));
const vectorsPath = join(here, "..", "..", "shared", "vectors.json");
const { wrap_vectors: wrapVectors } = JSON.parse(readFileSync(vectorsPath, "utf8"));

/** The therapist side of the vector, straight through node:crypto. */
function unwrapWith(
  therapistPrivPkcs8B64: string,
  ephemeralPubB64: string,
  wrapped: Buffer,
  userId: string,
  therapistId: string,
  therapistPubB64: string,
): Buffer {
  const priv = nodeCrypto.createPrivateKey({
    key: Buffer.from(therapistPrivPkcs8B64, "base64"),
    format: "der",
    type: "pkcs8",
  });
  const pub = nodeCrypto.createPublicKey({
    key: Buffer.from(ephemeralPubB64, "base64"),
    format: "der",
    type: "spki",
  });
  const shared = nodeCrypto.diffieHellman({ privateKey: priv, publicKey: pub });
  const kek = deriveWrapKek(
    shared,
    Buffer.from(ephemeralPubB64, "base64"),
    Buffer.from(therapistPubB64, "base64"),
  );
  return decrypt(kek, wrapped, buildAad(WRAP_CONTEXT, userId, therapistId));
}

describe("shared wrap vectors against the real TS sharing stack", () => {
  it("has vectors to check", () => {
    expect(wrapVectors.length).toBeGreaterThanOrEqual(3);
  });

  for (const [i, v] of wrapVectors.entries()) {
    it(`vector ${i}: the pinned KEK reproduces the pinned wrap bytes`, () => {
      // Derive the KEK from the vector's own fixed inputs — this is the
      // exact construction wrapDataKeyForTherapist runs on device.
      const priv = nodeCrypto.createPrivateKey({
        key: Buffer.from(v.ephemeral_priv_pkcs8, "base64"),
        format: "der",
        type: "pkcs8",
      });
      const pub = nodeCrypto.createPublicKey({
        key: Buffer.from(v.therapist_pub_spki, "base64"),
        format: "der",
        type: "spki",
      });
      const shared = nodeCrypto.diffieHellman({ privateKey: priv, publicKey: pub });
      const kek = deriveWrapKek(
        shared,
        Buffer.from(v.ephemeral_pub_spki, "base64"),
        Buffer.from(v.therapist_pub_spki, "base64"),
      );
      const aad = buildAad(WRAP_CONTEXT, v.user_id, v.therapist_id);
      const blob = encryptWithFixedNonce(kek, Buffer.from(v.data_key, "base64"), aad, Buffer.from(v.nonce, "base64"));
      expect(blob.toString("base64")).toBe(v.wrapped);
    });

    it(`vector ${i}: a fresh on-device wrap decrypts on the therapist side`, () => {
      const dataKey = Buffer.from(v.data_key, "base64");
      const wrap = wrapDataKeyForTherapist(dataKey, v.therapist_pub_spki, v.user_id, v.therapist_id);
      // Fresh ephemeral every grant — never the vector's.
      expect(wrap.ephemeralPubB64).not.toBe(v.ephemeral_pub_spki);
      const unwrapped = unwrapWith(
        v.therapist_priv_pkcs8,
        wrap.ephemeralPubB64,
        Buffer.from(wrap.wrappedKeyB64, "base64"),
        v.user_id,
        v.therapist_id,
        v.therapist_pub_spki,
      );
      expect(unwrapped.equals(dataKey)).toBe(true);
    });
  }
});

describe("wrap negative space", () => {
  const v = wrapVectors[0];

  it("two wraps of the same key differ (fresh ephemeral)", () => {
    const dataKey = Buffer.alloc(32, 9);
    const a = wrapDataKeyForTherapist(dataKey, v.therapist_pub_spki, v.user_id, v.therapist_id);
    const b = wrapDataKeyForTherapist(dataKey, v.therapist_pub_spki, v.user_id, v.therapist_id);
    expect(a.ephemeralPubB64).not.toBe(b.ephemeralPubB64);
    expect(a.wrappedKeyB64).not.toBe(b.wrappedKeyB64);
  });

  it("a wrap bound to the wrong patient does not unwrap", () => {
    const dataKey = Buffer.alloc(32, 5);
    const wrap = wrapDataKeyForTherapist(dataKey, v.therapist_pub_spki, "OTHER", v.therapist_id);
    expect(() =>
      unwrapWith(
        v.therapist_priv_pkcs8,
        wrap.ephemeralPubB64,
        Buffer.from(wrap.wrappedKeyB64, "base64"),
        v.user_id,
        v.therapist_id,
        v.therapist_pub_spki,
      ),
    ).toThrow(TamperError);
  });

  it("a wrap made for therapist A does not unwrap as therapist B", () => {
    const other = wrapVectors[1];
    const dataKey = Buffer.alloc(32, 6);
    // Wrapped to A's public key…
    const wrap = wrapDataKeyForTherapist(dataKey, v.therapist_pub_spki, v.user_id, v.therapist_id);
    // …but opened with B's private key: the ECDH secret differs.
    expect(() =>
      unwrapWith(
        other.therapist_priv_pkcs8,
        wrap.ephemeralPubB64,
        Buffer.from(wrap.wrappedKeyB64, "base64"),
        v.user_id,
        v.therapist_id,
        v.therapist_pub_spki,
      ),
    ).toThrow(TamperError);
  });

  it("rejects wrong-size data keys and malformed public keys", () => {
    expect(() =>
      wrapDataKeyForTherapist(Buffer.alloc(31), v.therapist_pub_spki, v.user_id, v.therapist_id),
    ).toThrow(/data key must be 32 bytes/);
    expect(() =>
      wrapDataKeyForTherapist(Buffer.alloc(32), "short", v.user_id, v.therapist_id),
    ).toThrow(/wrong format/);
    // 124 chars of base64 that decode to the wrong byte length.
    expect(() =>
      wrapDataKeyForTherapist(Buffer.alloc(32), "AAAA", v.user_id, v.therapist_id),
    ).toThrow(/wrong format/);
    // Exactly 124 chars (right b64 LENGTH) decoding to the wrong byte
    // count: the decoded-length check is the one that fires.
    expect(() =>
      wrapDataKeyForTherapist(Buffer.alloc(32), "A".repeat(124), v.user_id, v.therapist_id),
    ).toThrow(/wrong format/);
    // Valid-length b64, wrong bytes: ECDH with a non-point must throw.
    expect(() =>
      wrapDataKeyForTherapist(
        Buffer.alloc(32),
        Buffer.alloc(91, 1).toString("base64"),
        v.user_id,
        v.therapist_id,
      ),
    ).toThrow();
  });
});

tests/reconnectFlush.test.ts.source:
/**
 * flushQueueOnReconnect: the AppState-driven sync trigger. A foregrounding
 * with a live session and a non-empty queue flushes; throttled so a
 * foreground/background flap cannot stampede the server; failures leave
 * the queue intact for the next trigger.
 *
 * Module state (the throttle timestamp) is per-file here, so this suite
 * gets its own file — store.test.tsx asserts the AppState wiring against
 * the mocked module instead.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import storage from "./helpers/storageMock";

vi.mock("../src/api/client", () => {
  class ApiError extends Error {
    constructor(public status: number, message: string) {
      super(message);
    }
  }
  return {
    ApiError,
    api: {
      getUserId: vi.fn(async () => "alice"),
      createEntry: vi.fn(async () => ({})),
    },
    getBaseUrl: vi.fn(async () => "http://localhost:8000"),
  };
});

// eslint-disable-next-line @typescript-eslint/no-var-requires
const { api } = await import("../src/api/client") as any;
const { enqueue, queueLength, clearQueue, flushQueueOnReconnect } = await import("../src/offlineQueue");

const entry = (n: number) => ({
  userId: "alice",
  clientEntryId: `r-${n}`,
  blobB64: Buffer.alloc(40, n).toString("base64"),
  entryDate: "2026-09-01",
});

// The throttle timestamp is module state: each test starts the fake clock
// one minute later than the previous one so suites never share a window.
let clock: number | undefined;

beforeEach(() => {
  storage.__reset();
  vi.mocked(api.getUserId).mockClear();
  vi.mocked(api.getUserId).mockImplementation(async () => "alice");
  vi.mocked(api.createEntry).mockClear();
  vi.mocked(api.createEntry).mockImplementation(async () => ({}));
  vi.useFakeTimers();
  clock = (clock ?? Date.parse("2026-09-07T00:00:00Z")) + 60_000;
  vi.setSystemTime(clock);
});

afterEach(() => {
  vi.useRealTimers();
});

describe("flushQueueOnReconnect", () => {
  it("flushes a non-empty queue when a session exists", async () => {
    await enqueue(entry(1));
    await flushQueueOnReconnect();
    expect(api.createEntry).toHaveBeenCalledTimes(1);
    expect(await queueLength()).toBe(0);
  });

  it("does nothing when signed out or when the queue is empty", async () => {
    vi.mocked(api.getUserId).mockResolvedValue(null as never);
    await enqueue(entry(1));
    await flushQueueOnReconnect();
    expect(api.createEntry).not.toHaveBeenCalled();
    expect(await queueLength("alice")).toBe(1); // the entry waits for its owner

    // Empty queue: no upload, and the flush itself is skipped cheaply.
    // (Advance past the throttle window — this test's first call consumed it.)
    vi.advanceTimersByTime(11_000);
    vi.mocked(api.getUserId).mockResolvedValue("alice" as never);
    await clearQueue("alice");
    vi.mocked(api.createEntry).mockClear();
    await flushQueueOnReconnect();
    expect(api.createEntry).not.toHaveBeenCalled();
  });

  it("throttles rapid foreground/background flaps", async () => {
    await enqueue(entry(1));
    vi.mocked(api.createEntry).mockRejectedValue(new Error("offline")); // stays queued
    await flushQueueOnReconnect();
    await flushQueueOnReconnect(); // seconds later: throttled, not a stampede
    await flushQueueOnReconnect();
    expect(api.createEntry).toHaveBeenCalledTimes(1);
  });

  it("flushes again once the throttle window has passed", async () => {
    await enqueue(entry(1));
    vi.mocked(api.createEntry).mockRejectedValue(new Error("offline"));
    await flushQueueOnReconnect();
    expect(api.createEntry).toHaveBeenCalledTimes(1);
    vi.advanceTimersByTime(31_000); // past BOTH the 10s throttle and the item's ≤30s backoff
    await flushQueueOnReconnect();
    expect(api.createEntry).toHaveBeenCalledTimes(2);
  });

  it("a failed flush never throws and keeps the ciphertext queued", async () => {
    await enqueue(entry(1));
    vi.mocked(api.createEntry).mockRejectedValue(new Error("offline"));
    await expect(flushQueueOnReconnect()).resolves.toBeUndefined();
    expect(await queueLength()).toBe(1);
  });
});

tests/secureStore.test.ts.source:
/** Device-key custody regression tests: ciphertext may use AsyncStorage;
 * its key must not. */
import { beforeEach, describe, expect, it, vi } from "vitest";
import storage from "./helpers/storageMock";
import * as Keychain from "react-native-keychain";
import { secureStore, setSecureStoreBackend } from "../src/secureStore";

beforeEach(() => {
  storage.__reset();
  (Keychain as unknown as { __reset: () => void }).__reset();
  setSecureStoreBackend(null);
});

describe("secureStore", () => {
  it("round-trips encrypted values without persisting plaintext or a device key in AsyncStorage", async () => {
    await secureStore.setItem("@mindpattern/token", "tok-secret-value");
    expect(await secureStore.getItem("@mindpattern/token")).toBe("tok-secret-value");
    const encrypted = await storage.getItem("@mindpattern/token");
    expect(encrypted).not.toContain("tok-secret-value");
    expect(await storage.getItem("@mindpattern/device_k")).toBeNull();
    expect(await Keychain.getGenericPassword({ service: "com.mindpattern.session-device-key.v1" })).toMatchObject({
      username: "mindpattern-device-key",
    });
  });

  it("uses random encryption nonces for repeated plaintext values", async () => {
    await secureStore.setItem("a", "same");
    await secureStore.setItem("b", "same");
    expect(await storage.getItem("a")).not.toBe(await storage.getItem("b"));
  });

  it("reads corrupt payloads as absent rather than throwing", async () => {
    await secureStore.setItem("k", "v");
    await storage.setItem("k", "not-a-valid-envelope");
    expect(await secureStore.getItem("k")).toBeNull();
  });

  it("migrates a valid legacy device key into Keychain then removes the file copy", async () => {
    const legacy = Buffer.alloc(32, 9).toString("base64");
    await storage.setItem("@mindpattern/device_k", legacy);

    await secureStore.setItem("k", "v");
    expect(await storage.getItem("@mindpattern/device_k")).toBeNull();
    expect(await Keychain.getGenericPassword({ service: "com.mindpattern.session-device-key.v1" })).toMatchObject({
      password: legacy,
    });
    expect(await secureStore.getItem("k")).toBe("v");
  });

  it("removes malformed legacy key material instead of retaining it in AsyncStorage", async () => {
    await storage.setItem("@mindpattern/device_k", Buffer.alloc(31, 9).toString("base64"));
    await secureStore.setItem("k", "v");
    expect(await storage.getItem("@mindpattern/device_k")).toBeNull();
    expect(await secureStore.getItem("k")).toBe("v");
  });

  it("does not cache an unpersisted device key when native custody fails", async () => {
    const failing = {
      readDeviceKey: async () => null,
      writeDeviceKey: async () => { throw new Error("secure hardware unavailable"); },
      getItem: async (key: string) => storage.getItem(key),
      setItem: async (key: string, value: string) => storage.setItem(key, value),
      removeItem: async (key: string) => storage.removeItem(key),
    };
    setSecureStoreBackend(failing);
    await expect(secureStore.setItem("k", "v")).rejects.toThrow("secure hardware unavailable");
    expect(await storage.getItem("k")).toBeNull();
    setSecureStoreBackend(null);
    await secureStore.setItem("k", "v");
    expect(await secureStore.getItem("k")).toBe("v");
  });

  it("accepts a test-injected secure backend without touching AsyncStorage", async () => {
    const values = new Map<string, string>();
    const backend = {
      readDeviceKey: async () => values.get("device") ?? null,
      writeDeviceKey: async (value: string) => void values.set("device", value),
      getItem: async (key: string) => values.get(key) ?? null,
      setItem: async (key: string, value: string) => void values.set(key, value),
      removeItem: async (key: string) => void values.delete(key),
    };
    try {
      setSecureStoreBackend(backend);
      await secureStore.setItem("token", "private");
      expect(await storage.getItem("token")).toBeNull();
      expect(await secureStore.getItem("token")).toBe("private");
    } finally {
      setSecureStoreBackend(null);
    }
  });
});

tests/genericQuestions.test.ts.source:
/**
 * Parity + invariant tests for the embedded generic question pool.
 *
 * src/genericQuestions.ts is an EMBEDDED COPY of shared/generic_questions.json
 * (Metro cannot import outside the project root). This suite reads the
 * shared file from disk and pins array parity, the content invariants
 * (questions end with "?", no advice language), and the rotation
 * properties (same question all day, rotates daily, always in-pool).
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import { GENERIC_QUESTIONS, genericQuestionForDate } from "../src/genericQuestions";

const here = dirname(fileURLToPath(import.meta.url));
const shared = JSON.parse(readFileSync(join(here, "..", "..", "shared", "generic_questions.json"), "utf8")) as {
  v: number;
  questions: string[];
};

describe("shared/generic_questions.json parity", () => {
  it("embeds the pool exactly", () => {
    expect(shared.v).toBe(1);
    expect([...GENERIC_QUESTIONS]).toEqual(shared.questions);
  });

  it("honors the content invariants: questions only, no advice language", () => {
    for (const question of GENERIC_QUESTIONS) {
      expect(question.endsWith("?")).toBe(true);
      expect(question.toLowerCase()).not.toContain("should");
    }
  });
});

describe("genericQuestionForDate rotation", () => {
  it("is deterministic: the same date always yields the same question", () => {
    expect(genericQuestionForDate("2026-09-07")).toBe(genericQuestionForDate("2026-09-07"));
  });

  it("always returns a pool member", () => {
    for (let day = 1; day <= 30; day++) {
      const date = `2026-09-${String(day).padStart(2, "0")}`;
      expect(GENERIC_QUESTIONS).toContain(genericQuestionForDate(date));
    }
  });

  it("rotates daily over a month (and month boundaries stay stable)", () => {
    const seen = new Set<string>();
    for (let day = 1; day <= 30; day++) {
      seen.add(genericQuestionForDate(`2026-09-${String(day).padStart(2, "0")}`));
    }
    // Not a constant pick; adjacent days step through the pool.
    expect(seen.size).toBeGreaterThanOrEqual(4);
    // Month boundaries are just dates: deterministic and in-pool.
    expect(GENERIC_QUESTIONS).toContain(genericQuestionForDate("2026-09-30"));
    expect(GENERIC_QUESTIONS).toContain(genericQuestionForDate("2026-10-01"));
    // The default form (today) returns a pool member.
    expect(GENERIC_QUESTIONS).toContain(genericQuestionForDate());
  });
});

